-- Formal catalog tables for word books and vocabulary items, mirroring
-- src/data/wordBooks.ts and src/data/vocabulary/*.json (the app's current
-- bundled data source, which this migration does not replace or remove).
-- Seeds the exact same ids, content, and per-book ordering as those files
-- so a future switch to reading from the database is a drop-in change.
create table public.word_books (
  id text primary key
    check (length(trim(id)) > 0),

  title text not null
    check (length(trim(title)) > 0),

  chinese_title text not null
    check (length(trim(chinese_title)) > 0),

  description text not null
    check (length(trim(description)) > 0),

  category text not null
    check (length(trim(category)) > 0),

  -- Display order among word books (0-based), matching src/data/wordBooks.ts.
  sort_order integer not null
    check (sort_order >= 0),

  is_active boolean not null default true,

  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

-- Mirrors src/types/vocabulary.ts's VocabularyItem. Optional fields on that
-- type (partOfSpeech, englishDefinition, exampleSentence,
-- exampleTranslation, ipa, pronunciationText) are nullable here for the
-- same reason.
create table public.vocabulary_items (
  -- Mirrors the local VocabularyItem.id (e.g. "dev-stakeholder") verbatim —
  -- ids are never regenerated, so this stays the single stable identifier
  -- shared with user_word_progress.vocabulary_item_id (still a plain text
  -- column there with no foreign key, per that table's existing migration).
  id text primary key
    check (length(trim(id)) > 0),

  word_book_id text not null
    references public.word_books (id),

  term text not null
    check (length(trim(term)) > 0),

  chinese_meaning text not null
    check (length(trim(chinese_meaning)) > 0),

  part_of_speech text,
  english_definition text,
  example_sentence text,
  example_translation text,

  tags text[] not null default '{}',

  ipa text,
  pronunciation_text text,

  -- Position within its word book (0-based), matching the source JSON's
  -- array order.
  sort_order integer not null
    check (sort_order >= 0),

  is_active boolean not null default true,

  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create unique index word_books_sort_order_idx
  on public.word_books (sort_order);

-- No separate single-column index on word_book_id: this composite index
-- already starts with word_book_id, so it covers both "sort_order within
-- this book" queries and plain word_book_id lookups.
create unique index vocabulary_items_word_book_id_sort_order_idx
  on public.vocabulary_items (word_book_id, sort_order);

-- Supports "does this term already exist in this book" lookups using the
-- same normalization rule as scripts/validate-vocabulary.mjs (trim,
-- lowercase, collapse whitespace); unique so the database itself rejects a
-- duplicate term within the same book, not just app-side validation.
create unique index vocabulary_items_word_book_id_normalized_term_idx
  on public.vocabulary_items (word_book_id, lower(regexp_replace(trim(term), '\s+', ' ', 'g')));

alter table public.word_books enable row level security;
alter table public.vocabulary_items enable row level security;

-- Start from a clean slate rather than assuming project-level default
-- grants, then hand out exactly the privileges each role needs: read-only
-- reference data for signed-in users, nothing for anon, no write path from
-- the client at all (not even a policy exists for insert/update/delete).
revoke all on table public.word_books from anon;
revoke all on table public.word_books from authenticated;
grant select on table public.word_books to authenticated;

revoke all on table public.vocabulary_items from anon;
revoke all on table public.vocabulary_items from authenticated;
grant select on table public.vocabulary_items to authenticated;

create policy "word_books_select_all"
  on public.word_books
  for select
  to authenticated
  using (true);

create policy "vocabulary_items_select_all"
  on public.vocabulary_items
  for select
  to authenticated
  using (true);

-- Seed data: word books first (vocabulary_items.word_book_id references
-- them), then vocabulary items. No ON CONFLICT clause — a duplicate or
-- conflicting id here means the seed data itself is wrong, so the
-- migration must fail loudly rather than silently skip the row.
