  ('dev-first-class-function', 'developer', 'first-class function', '一等函数', 'n.', 'A function that can be assigned to a variable, passed as an argument, or returned like any other value.', 'Because functions are first-class functions here, you can store one in an array.', '因为这里的函数是一等函数，你可以把一个函数存进数组里。', ARRAY['fp', 'coding']::text[], null, null, 56, true),
  ('dev-lambda-expression', 'developer', 'lambda expression', '匿名函数表达式', 'n.', 'A short, anonymous function defined inline without a separate name.', 'We passed a lambda expression directly instead of defining a named comparator function.', '我们直接传入了一个匿名函数表达式，而不是单独定义一个具名的比较函数。', ARRAY['fp', 'coding']::text[], null, null, 57, true),
  ('dev-currying', 'developer', 'currying', '柯里化', 'n.', 'Transforming a function that takes multiple arguments into a sequence of functions that each take one argument.', 'Currying let us pre-fill the API client with the base URL and reuse it everywhere.', '通过柯里化，我们预先给这个 API 客户端填入了基础地址，然后就可以到处复用了。', ARRAY['fp', 'coding']::text[], null, null, 58, true),
  ('dev-abstract-class', 'developer', 'abstract class', '抽象类', 'n.', 'A class that cannot be instantiated directly and is meant to be extended by subclasses.', 'The abstract class defines the shared workflow, while each subclass fills in the details.', '这个抽象类定义了共享的流程，每个子类负责填充具体细节。', ARRAY['oop', 'coding']::text[], null, null, 59, true),
  ('dev-access-modifier', 'developer', 'access modifier', '访问修饰符', 'n.', 'A keyword that controls the visibility of a class member, such as public, private, or protected.', 'Marking the field with a private access modifier stops other classes from reading it directly.', '把这个字段标记为 private 访问修饰符，可以阻止其他类直接读取它。', ARRAY['oop', 'coding']::text[], null, null, 60, true),
  ('dev-getter-setter', 'developer', 'getter and setter', '取值器与赋值器', 'n.', 'Methods used to read (get) and write (set) the value of a private field in a controlled way.', 'We added a setter that validates the age before it''s stored on the object.', '我们加了一个赋值器，在存入对象之前先校验年龄是否合法。', ARRAY['oop', 'coding']::text[], null, null, 61, true),
  ('dev-duck-typing', 'developer', 'duck typing', '鸭子类型', 'n.', 'A style of typing where an object''s suitability is determined by the methods it has, not its declared type.', 'Thanks to duck typing, any object with a read() method works here, regardless of its class.', '多亏了鸭子类型，任何拥有 read() 方法的对象都能在这里使用，不管它属于哪个类。', ARRAY['oop', 'coding']::text[], null, null, 62, true),
  ('dev-instance', 'developer', 'instance', '实例', 'n.', 'A specific object created from a class.', 'Each request creates a new instance of the handler class.', '每个请求都会创建一个新的处理器类实例。', ARRAY['oop', 'coding']::text[], null, null, 63, true),
  ('dev-superclass', 'developer', 'superclass', '父类；超类', 'n.', 'The class that another class inherits from.', 'The superclass provides a default implementation that most subclasses never need to change.', '父类提供了一个默认实现，大多数子类都不需要修改它。', ARRAY['oop', 'coding']::text[], null, null, 64, true),
  ('dev-subclass', 'developer', 'subclass', '子类', 'n.', 'A class that inherits properties and behavior from another class.', 'Create a subclass if you only need to change how one method behaves.', '如果你只需要改变某一个方法的行为，创建一个子类就够了。', ARRAY['oop', 'coding']::text[], null, null, 65, true),
  ('dev-private-member', 'developer', 'private member', '私有成员', 'n.', 'A field or method that is only accessible from within the class that defines it.', 'The connection pool is a private member so external code can''t reach into it directly.', '这个连接池是一个私有成员，外部代码无法直接访问它。', ARRAY['oop', 'coding']::text[], null, null, 66, true),
  ('dev-static-method', 'developer', 'static method', '静态方法', 'n.', 'A method that belongs to a class itself rather than to any particular instance.', 'We added a static method to create a default instance without exposing the constructor.', '我们加了一个静态方法来创建默认实例，同时不暴露构造函数。', ARRAY['oop', 'coding']::text[], null, null, 67, true),
  ('dev-immutable-object', 'developer', 'immutable object', '不可变对象', 'n.', 'An object whose state cannot be modified after it is created.', 'We treat the configuration as an immutable object once it has been loaded.', '配置一旦加载完成，我们就把它当作一个不可变对象来处理。', ARRAY['oop', 'coding']::text[], null, null, 68, true),
  ('dev-protocol', 'developer', 'protocol', '协议（语言层面的接口约定）', 'n.', 'A defined set of methods or properties that a type promises to implement.', 'Conforming to the protocol lets our custom view work with the shared list component.', '遵循这个协议让我们的自定义视图可以和共享的列表组件一起使用。', ARRAY['oop', 'coding']::text[], null, null, 69, true),
  ('dev-array', 'developer', 'array', '数组', 'n.', 'A data structure that stores a fixed-size, ordered collection of elements accessible by index.', 'Looking up an element by index in an array runs in constant time.', '在数组中按索引查找元素的时间复杂度是常数级的。', ARRAY['data-structures', 'algorithms']::text[], null, null, 70, true),
  ('dev-linked-list', 'developer', 'linked list', '链表', 'n.', 'A linear data structure where each element points to the next, allowing efficient insertion and removal.', 'We used a linked list here because items are inserted in the middle far more often than they''re looked up by index.', '我们在这里用了链表，因为元素在中间插入的频率远高于按索引查找。', ARRAY['data-structures', 'algorithms']::text[], null, null, 71, true),
  ('dev-stack', 'developer', 'stack', '栈', 'n.', 'A last-in, first-out data structure where elements are added and removed from the same end.', 'The undo feature is implemented with a stack of previous states.', '撤销功能是用一个存放历史状态的栈实现的。', ARRAY['data-structures', 'algorithms']::text[], null, null, 72, true),
  ('dev-queue', 'developer', 'queue', '队列', 'n.', 'A first-in, first-out data structure where elements are added at one end and removed from the other.', 'Incoming jobs are placed in a queue and processed in the order they arrive.', '新进来的任务会被放入一个队列，并按到达顺序依次处理。', ARRAY['data-structures', 'algorithms']::text[], null, null, 73, true),
  ('dev-hash-table', 'developer', 'hash table', '哈希表', 'n.', 'A data structure that maps keys to values using a hash function for fast lookup.', 'A hash table gives us near constant-time lookups by user id.', '哈希表让我们能以接近常数级的时间按用户 id 进行查找。', ARRAY['data-structures', 'algorithms']::text[], null, null, 74, true),
  ('dev-binary-tree', 'developer', 'binary tree', '二叉树', 'n.', 'A tree data structure in which each node has at most two children.', 'The autocomplete index is stored as a binary tree sorted by prefix.', '自动补全的索引是以二叉树的形式按前缀排序存储的。', ARRAY['data-structures', 'algorithms']::text[], null, null, 75, true),
  ('dev-binary-search', 'developer', 'binary search', '二分查找', 'n.', 'An algorithm that finds a target value in a sorted collection by repeatedly halving the search range.', 'Binary search cut the lookup time from linear to logarithmic.', '二分查找把查找时间从线性复杂度降到了对数复杂度。', ARRAY['data-structures', 'algorithms']::text[], null, null, 76, true),
  ('dev-sorting-algorithm', 'developer', 'sorting algorithm', '排序算法', 'n.', 'An algorithm that arranges elements of a collection into a specific order.', 'We swapped in a more efficient sorting algorithm once the dataset grew past a million rows.', '当数据集超过一百万行后，我们换了一个更高效的排序算法。', ARRAY['data-structures', 'algorithms']::text[], null, null, 77, true),
  ('dev-time-complexity', 'developer', 'time complexity', '时间复杂度', 'n.', 'A measure of how the running time of an algorithm grows as the input size increases.', 'The interviewer asked me to explain the time complexity of my solution.', '面试官让我解释一下这个解法的时间复杂度。', ARRAY['data-structures', 'algorithms']::text[], null, null, 78, true),
  ('dev-space-complexity', 'developer', 'space complexity', '空间复杂度', 'n.', 'A measure of how much memory an algorithm uses relative to its input size.', 'This approach trades higher space complexity for a much faster runtime.', '这种方法用更高的空间复杂度换取了快得多的运行速度。', ARRAY['data-structures', 'algorithms']::text[], null, null, 79, true),
  ('dev-big-o-notation', 'developer', 'Big O notation', '大 O 表示法', 'n.', 'A mathematical notation used to describe the upper-bound growth rate of an algorithm''s time or space usage.', 'In Big O notation, this nested loop is O(n squared).', '用大 O 表示法来说，这个嵌套循环的复杂度是 O(n 的平方)。', ARRAY['data-structures', 'algorithms']::text[], null, null, 80, true),
  ('dev-depth-first-search', 'developer', 'depth-first search', '深度优先搜索', 'n.', 'A graph or tree traversal algorithm that explores as far as possible along each branch before backtracking.', 'We used depth-first search to detect a cycle in the dependency graph.', '我们用深度优先搜索来检测依赖图中是否存在环。', ARRAY['data-structures', 'algorithms']::text[], null, null, 81, true),
  ('dev-breadth-first-search', 'developer', 'breadth-first search', '广度优先搜索', 'n.', 'A graph or tree traversal algorithm that explores all neighbors at the current depth before moving deeper.', 'Breadth-first search finds the shortest path in an unweighted graph.', '广度优先搜索可以在无权图中找到最短路径。', ARRAY['data-structures', 'algorithms']::text[], null, null, 82, true),
  ('dev-dynamic-programming', 'developer', 'dynamic programming', '动态规划', 'n.', 'A technique that solves a problem by breaking it into overlapping subproblems and caching their results.', 'Dynamic programming avoided recomputing the same subproblem thousands of times.', '动态规划避免了同一个子问题被重复计算成千上万次。', ARRAY['data-structures', 'algorithms']::text[], null, null, 83, true),
  ('dev-greedy-algorithm', 'developer', 'greedy algorithm', '贪心算法', 'n.', 'An algorithm that makes the locally optimal choice at each step, hoping to find a global optimum.', 'A greedy algorithm gives an optimal solution here because the problem has the right structure.', '因为这个问题的结构合适，用贪心算法就能得到最优解。', ARRAY['data-structures', 'algorithms']::text[], null, null, 84, true),
  ('dev-divide-and-conquer', 'developer', 'divide and conquer', '分治法', 'phr.', 'A strategy that solves a problem by splitting it into smaller subproblems, solving them, and combining the results.', 'Merge sort is a classic example of divide and conquer.', '归并排序是分治法的一个经典例子。', ARRAY['data-structures', 'algorithms']::text[], null, null, 85, true),
  ('dev-base-case', 'developer', 'base case', '（递归的）基本情况', 'n.', 'The condition in a recursive function that stops further recursive calls.', 'Forgetting the base case is a common reason recursive functions overflow the stack.', '忘记写基本情况是递归函数导致栈溢出的常见原因。', ARRAY['data-structures', 'algorithms']::text[], null, null, 86, true),
  ('dev-hash-collision', 'developer', 'hash collision', '哈希冲突', 'n.', 'A situation where two different keys produce the same hash value.', 'The hash table handles a hash collision by chaining entries in a small linked list.', '这个哈希表通过在同一位置用小型链表串联条目来处理哈希冲突。', ARRAY['data-structures', 'algorithms']::text[], null, null, 87, true),
  ('dev-balanced-tree', 'developer', 'balanced tree', '平衡树', 'n.', 'A tree structure that automatically keeps its height low so operations stay efficient.', 'The database index is backed by a balanced tree to keep lookups fast even as it grows.', '这个数据库索引底层是一棵平衡树，即使数据量增长，查找依然很快。', ARRAY['data-structures', 'algorithms']::text[], null, null, 88, true),
  ('dev-heap', 'developer', 'heap', '堆', 'n.', 'A tree-based data structure that keeps the smallest (or largest) element quickly accessible at the root.', 'We used a heap to always process the task with the earliest deadline first.', '我们用堆来保证总是优先处理截止时间最早的任务。', ARRAY['data-structures', 'algorithms']::text[], null, null, 89, true),
  ('dev-priority-queue', 'developer', 'priority queue', '优先队列', 'n.', 'A queue where each element has a priority, and elements with higher priority are served first.', 'The scheduler uses a priority queue so urgent jobs jump ahead of routine ones.', '调度器使用优先队列，让紧急任务能排到常规任务前面。', ARRAY['data-structures', 'algorithms']::text[], null, null, 90, true),
  ('dev-trie', 'developer', 'trie', '字典树；前缀树', 'n.', 'A tree-like data structure used to store strings efficiently, especially for prefix lookups.', 'A trie made prefix matching for search suggestions much faster.', '字典树让搜索建议的前缀匹配速度快了很多。', ARRAY['data-structures', 'algorithms']::text[], null, null, 91, true),
  ('dev-set', 'developer', 'set', '集合', 'n.', 'A data structure that stores unique values with no duplicates.', 'We store the visited node ids in a set to avoid processing the same node twice.', '我们把已访问节点的 id 存进一个集合，避免同一个节点被处理两次。', ARRAY['data-structures', 'algorithms']::text[], null, null, 92, true),
  ('dev-hash-map', 'developer', 'hash map', '哈希映射', 'n.', 'A key-value data structure implemented using a hash table for fast lookup, insertion, and deletion.', 'We built a hash map from user id to session so lookups don''t need a database round trip.', '我们构建了一个从用户 id 到会话的哈希映射，这样查找就不需要访问数据库了。', ARRAY['data-structures', 'algorithms']::text[], null, null, 93, true),
  ('dev-two-pointer-technique', 'developer', 'two-pointer technique', '双指针技巧', 'n.', 'An algorithmic technique that uses two indices moving through a data structure to solve a problem in one pass.', 'The two-pointer technique solved this in linear time without any extra memory.', '双指针技巧在不占用额外内存的情况下，用线性时间解决了这个问题。', ARRAY['data-structures', 'algorithms']::text[], null, null, 94, true),
  ('dev-sliding-window', 'developer', 'sliding window', '滑动窗口', 'n.', 'A technique that maintains a subset of elements as a window that moves across a sequence.', 'A sliding window let us compute the moving average without recalculating the whole sum each time.', '滑动窗口让我们不用每次都重新计算总和，就能得到移动平均值。', ARRAY['data-structures', 'algorithms']::text[], null, null, 95, true),
  ('dev-in-place-algorithm', 'developer', 'in-place algorithm', '原地算法', 'n.', 'An algorithm that transforms input using only a small, constant amount of extra memory.', 'We rewrote the sort as an in-place algorithm to cut memory usage on large arrays.', '我们把排序改写成了原地算法，以降低处理大数组时的内存占用。', ARRAY['data-structures', 'algorithms']::text[], null, null, 96, true),
  ('dev-amortized-complexity', 'developer', 'amortized complexity', '均摊复杂度', 'n.', 'The average performance of an operation over a sequence of operations, even if some individual operations are slow.', 'Appending to a dynamic array has amortized constant-time complexity even though occasional resizes are slower.', '向动态数组追加元素的均摊复杂度是常数级的，尽管偶尔的扩容操作会更慢。', ARRAY['data-structures', 'algorithms']::text[], null, null, 97, true),
  ('dev-graph-traversal', 'developer', 'graph traversal', '图遍历', 'n.', 'The process of visiting all the nodes in a graph in a systematic way.', 'Graph traversal is used here to find every service that depends on this one.', '这里用图遍历来找出所有依赖这个服务的其他服务。', ARRAY['data-structures', 'algorithms']::text[], null, null, 98, true),
  ('dev-commit', 'developer', 'commit', '提交（代码变更）', 'n./v.', 'A saved snapshot of changes in version control, or the act of saving one.', 'Split this into smaller commits so the history is easier to review.', '把这个拆成更小的提交，这样历史记录会更容易review。', ARRAY['git', 'collaboration']::text[], null, null, 99, true),
  ('dev-branch', 'developer', 'branch', '分支', 'n.', 'An independent line of development in version control that diverges from the main codebase.', 'Create a new branch before you start working on the login redesign.', '开始做登录页重设计之前，先创建一个新分支。', ARRAY['git', 'collaboration']::text[], null, null, 100, true),
  ('dev-merge', 'developer', 'merge', '合并', 'v./n.', 'Combining changes from one branch into another.', 'We merge the feature branch into main once all the checks pass.', '所有检查通过之后，我们才会把这个功能分支合并进 main。', ARRAY['git', 'collaboration']::text[], null, null, 101, true),
  ('dev-merge-conflict', 'developer', 'merge conflict', '合并冲突', 'n.', 'A situation where Git cannot automatically combine changes because the same lines were edited differently.', 'There''s a merge conflict in the config file — two branches touched the same lines.', '配置文件里出现了合并冲突——两个分支修改了同一行代码。', ARRAY['git', 'collaboration']::text[], null, null, 102, true),
  ('dev-pull-request', 'developer', 'pull request', '拉取请求（PR）', 'n.', 'A request to merge changes from one branch into another, usually reviewed before being accepted.', 'Open a pull request once your changes are ready for review.', '改动准备好接受审查后，就提交一个拉取请求。', ARRAY['git', 'collaboration']::text[], null, null, 103, true),
  ('dev-rebase', 'developer', 'rebase', '变基', 'v.', 'To move or reapply commits from one branch onto another, producing a cleaner, linear history.', 'Rebase your branch onto the latest main before opening the pull request.', '在提交拉取请求之前，先把你的分支变基到最新的 main 上。', ARRAY['git', 'collaboration']::text[], null, null, 104, true),
  ('dev-fork', 'developer', 'fork', '复刻（仓库）', 'n./v.', 'A personal copy of someone else''s repository that you can modify independently.', 'External contributors need to fork the repository before submitting a pull request.', '外部贡献者需要先复刻这个仓库，才能提交拉取请求。', ARRAY['git', 'collaboration']::text[], null, null, 105, true),
  ('dev-clone', 'developer', 'clone', '克隆（仓库）', 'v.', 'To create a local copy of a remote repository, including its full history.', 'Clone the repository and run the setup script to get started.', '克隆这个仓库，然后运行安装脚本即可开始。', ARRAY['git', 'collaboration']::text[], null, null, 106, true),
  ('dev-checkout', 'developer', 'checkout', '切换（分支或提交）', 'v./n.', 'To switch the working directory to a different branch or commit.', 'Checkout the previous commit to confirm the bug wasn''t there before.', '切换到上一个提交，确认之前是否存在这个 bug。', ARRAY['git', 'collaboration']::text[], null, null, 107, true),
  ('dev-staging-area', 'developer', 'staging area', '暂存区', 'n.', 'The area in Git where changes are collected before they are committed.', 'Only the files added to the staging area will be included in the next commit.', '只有添加到暂存区的文件才会包含在下一次提交中。', ARRAY['git', 'collaboration']::text[], null, null, 108, true),
  ('dev-commit-history', 'developer', 'commit history', '提交历史', 'n.', 'The chronological record of all commits made to a repository.', 'I went through the commit history to find when this behavior changed.', '我翻查了提交历史，找出这个行为是什么时候改变的。', ARRAY['git', 'collaboration']::text[], null, null, 109, true),
  ('dev-cherry-pick', 'developer', 'cherry-pick', '挑选提交（cherry-pick）', 'v.', 'To apply a specific commit from one branch onto another without merging the whole branch.', 'We cherry-picked the security fix into the release branch.', '我们把这个安全修复单独挑选出来，应用到了发布分支上。', ARRAY['git', 'collaboration']::text[], null, null, 110, true),
  ('dev-revert', 'developer', 'revert', '回滚（提交）', 'v.', 'To create a new commit that undoes the changes introduced by an earlier commit.', 'We had to revert the last commit because it broke the build.', '我们不得不回滚上一个提交，因为它把构建搞坏了。', ARRAY['git', 'collaboration']::text[], null, null, 111, true),
  ('dev-squash-commits', 'developer', 'squash commits', '压缩提交', 'phr.', 'Combining multiple commits into a single commit before merging.', 'Squash commits before merging so the history stays clean.', '合并之前先压缩提交，让历史记录保持整洁。', ARRAY['git', 'collaboration']::text[], null, null, 112, true),
  ('dev-git-tag', 'developer', 'git tag', 'Git 标签', 'n.', 'A reference that marks a specific commit, commonly used to mark release points.', 'We created a git tag for every production release so we can roll back precisely.', '我们为每次生产环境发布都创建了一个 Git 标签，以便精确回滚。', ARRAY['git', 'collaboration']::text[], null, null, 113, true),
  ('dev-upstream-branch', 'developer', 'upstream branch', '上游分支', 'n.', 'The remote branch that a local branch tracks and pulls updates from.', 'Set the upstream branch so `git pull` knows where to fetch changes from.', '设置好上游分支，这样 `git pull` 才知道要从哪里拉取更新。', ARRAY['git', 'collaboration']::text[], null, null, 114, true),
  ('dev-main-branch', 'developer', 'main branch', '主分支', 'n.', 'The primary branch of a repository that usually reflects the stable, production-ready code.', 'Nothing gets merged into the main branch without passing code review.', '任何改动都必须通过代码审查才能合并进主分支。', ARRAY['git', 'collaboration']::text[], null, null, 115, true),
  ('dev-feature-branch', 'developer', 'feature branch', '功能分支', 'n.', 'A branch created to develop a single feature in isolation before merging it back.', 'Each feature branch is deleted automatically once it''s merged.', '每个功能分支在合并之后都会被自动删除。', ARRAY['git', 'collaboration']::text[], null, null, 116, true),
  ('dev-hotfix-branch', 'developer', 'hotfix branch', '热修复分支', 'n.', 'A short-lived branch created to urgently fix a critical bug in production.', 'We cut a hotfix branch directly from the production tag to fix the outage.', '为了修复这次故障，我们直接从生产环境的标签上拉出了一个热修复分支。', ARRAY['git', 'collaboration']::text[], null, null, 117, true),
  ('dev-changelog', 'developer', 'changelog', '变更日志', 'n.', 'A file or document that records notable changes made to a project over time.', 'Update the changelog before you tag the new release.', '打新版本标签之前，先更新变更日志。', ARRAY['git', 'collaboration']::text[], null, null, 118, true),
  ('dev-diff', 'developer', 'diff', '差异对比', 'n.', 'A representation of the differences between two versions of a file or codebase.', 'The diff shows exactly which lines were added and removed.', '这个差异对比清楚地显示出哪些行被新增了，哪些行被删除了。', ARRAY['git', 'collaboration']::text[], null, null, 119, true),
  ('dev-git-blame', 'developer', 'git blame', 'Git 追溯（查看每行的提交作者）', 'n.', 'A command that shows who last modified each line of a file and in which commit.', 'I ran git blame to find out who added this workaround and why.', '我用 git blame 查了一下是谁加的这个临时解决方案，以及原因是什么。', ARRAY['git', 'collaboration']::text[], null, null, 120, true),
  ('dev-gitignore', 'developer', '.gitignore', 'Git 忽略文件配置', 'n.', 'A configuration file that lists files and folders Git should not track.', 'Add the build folder to .gitignore so it never gets committed.', '把构建输出目录加进 .gitignore，避免它被提交进仓库。', ARRAY['git', 'collaboration']::text[], null, 'dot git ignore', 121, true),
  ('dev-version-control', 'developer', 'version control', '版本控制', 'n.', 'A system for tracking and managing changes to code or files over time.', 'Everything in this project, including configuration, is kept under version control.', '这个项目里的一切，包括配置文件，都纳入了版本控制。', ARRAY['git', 'collaboration']::text[], null, null, 122, true),
  ('dev-pair-programming', 'developer', 'pair programming', '结对编程', 'n.', 'A practice where two developers work together at one workstation, one writing code and the other reviewing.', 'We used pair programming to onboard the new hire onto the payment module.', '我们通过结对编程，帮助新员工上手了支付模块。', ARRAY['git', 'collaboration']::text[], null, null, 123, true),
  ('dev-code-owner', 'developer', 'code owner', '代码负责人', 'n.', 'A person or team designated as responsible for reviewing changes to a specific part of the codebase.', 'The code owner for this module has to approve before the pull request can merge.', '这个模块的代码负责人必须先批准，拉取请求才能合并。', ARRAY['git', 'collaboration']::text[], null, null, 124, true),
  ('dev-commit-message', 'developer', 'commit message', '提交信息', 'n.', 'The text description attached to a commit explaining what it changes and why.', 'Write a clear commit message so reviewers understand the intent without reading every line.', '写一条清晰的提交信息，让审查者不用读完每一行代码就能理解改动意图。', ARRAY['git', 'collaboration']::text[], null, null, 125, true),
  ('dev-force-push', 'developer', 'force push', '强制推送', 'n./v.', 'Overwriting a remote branch''s history with your local branch, ignoring conflicts.', 'Never force push to the main branch — you could overwrite someone else''s commits.', '永远不要对主分支进行强制推送——这可能会覆盖别人的提交。', ARRAY['git', 'collaboration']::text[], null, null, 126, true),
  ('dev-git-hook', 'developer', 'git hook', 'Git 钩子', 'n.', 'A script that runs automatically at certain points in the Git workflow, such as before a commit.', 'A pre-commit git hook runs the linter before every commit.', '一个 pre-commit 的 Git 钩子会在每次提交前运行代码检查工具。', ARRAY['git', 'collaboration']::text[], null, null, 127, true),
  ('dev-monorepo', 'developer', 'monorepo', '单体仓库', 'n.', 'A single repository that holds the code for multiple projects or packages.', 'We moved to a monorepo so the frontend and backend teams could share code more easily.', '我们迁移到了单体仓库，让前端和后端团队更容易共享代码。', ARRAY['git', 'collaboration']::text[], null, null, 128, true),
  ('dev-breakpoint', 'developer', 'breakpoint', '断点', 'n.', 'A marker set in code that pauses execution at that line so it can be inspected.', 'Set a breakpoint right before the function returns to inspect the final state.', '在函数返回之前设一个断点，检查最终状态。', ARRAY['debugging', 'troubleshooting']::text[], null, null, 129, true),
  ('dev-stack-trace', 'developer', 'stack trace', '调用栈追踪', 'n.', 'A report of the active function calls at the point an error occurred.', 'The stack trace points to a null value three layers deep in the call chain.', '调用栈追踪显示问题出在调用链第三层的一个空值上。', ARRAY['debugging', 'troubleshooting']::text[], null, null, 130, true),
  ('dev-log-level', 'developer', 'log level', '日志级别', 'n.', 'A category, such as debug, info, warning, or error, that indicates the severity of a log message.', 'We raised the log level to debug temporarily to catch more detail.', '我们临时把日志级别调到了 debug，以捕获更多细节。', ARRAY['debugging', 'troubleshooting']::text[], null, null, 131, true),
  ('dev-root-cause', 'developer', 'root cause', '根本原因', 'n.', 'The underlying reason an issue occurred, as opposed to its visible symptoms.', 'The root cause turned out to be a misconfigured timeout, not the code itself.', '最后发现根本原因是超时配置错误，而不是代码本身的问题。', ARRAY['debugging', 'troubleshooting']::text[], null, null, 132, true),
  ('dev-reproduce-a-bug', 'developer', 'reproduce a bug', '复现 bug', 'phr.', 'To trigger the same failure again, usually as the first step in diagnosing it.', 'I couldn''t reproduce the bug locally until I matched the user''s exact device settings.', '在我复制了用户的确切设备设置之前，我一直没能在本地复现这个 bug。', ARRAY['debugging', 'troubleshooting']::text[], null, null, 133, true),
  ('dev-memory-leak', 'developer', 'memory leak', '内存泄漏', 'n.', 'A bug where a program fails to release memory it no longer needs, causing usage to grow over time.', 'The app''s memory leak only became noticeable after running for several hours.', '这个应用的内存泄漏问题运行几个小时后才变得明显。', ARRAY['debugging', 'troubleshooting']::text[], null, null, 134, true),
  ('dev-race-condition', 'developer', 'race condition', '竞态条件', 'n.', 'A bug that occurs when the outcome depends on the unpredictable timing of concurrent operations.', 'The intermittent failure was caused by a race condition between two threads writing the same file.', '这个偶发的失败是两个线程写同一个文件时的竞态条件导致的。', ARRAY['debugging', 'troubleshooting']::text[], null, null, 135, true),
  ('dev-deadlock', 'developer', 'deadlock', '死锁', 'n.', 'A state where two or more processes are stuck waiting for each other, so none of them can proceed.', 'The service hung because two threads ended up in a deadlock over the same locks.', '两个线程因为争夺同一批锁陷入死锁，导致服务卡住了。', ARRAY['debugging', 'troubleshooting']::text[], null, null, 136, true),
  ('dev-null-reference-exception', 'developer', 'null reference exception', '空引用异常', 'n.', 'An error thrown when code tries to access a member of an object that is null or not set.', 'The crash logs are full of null reference exceptions from the same screen.', '崩溃日志里全是来自同一个页面的空引用异常。', ARRAY['debugging', 'troubleshooting']::text[], null, null, 137, true),
  ('dev-crash-report', 'developer', 'crash report', '崩溃报告', 'n.', 'A record automatically generated when an application crashes, capturing the state and stack trace at the time.', 'We prioritize bugs based on how many crash reports they generate.', '我们会根据崩溃报告的数量来给 bug 排优先级。', ARRAY['debugging', 'troubleshooting']::text[], null, null, 138, true),
  ('dev-exception-handling', 'developer', 'exception handling', '异常处理', 'n.', 'Code written to detect and respond to errors so the program can recover or fail gracefully.', 'Better exception handling would have shown the user a friendly message instead of a blank screen.', '如果有更好的异常处理，用户看到的就会是一条友好的提示，而不是一片空白。', ARRAY['debugging', 'troubleshooting']::text[], null, null, 139, true),
  ('dev-try-catch-block', 'developer', 'try-catch block', 'try-catch 语句块', 'n.', 'A code structure that attempts an operation and defines how to handle any error it throws.', 'Wrap the network call in a try-catch block so a failed request doesn''t crash the app.', '把这次网络请求包在 try-catch 语句块里，这样请求失败就不会导致应用崩溃。', ARRAY['debugging', 'troubleshooting']::text[], null, null, 140, true),
  ('dev-error-message', 'developer', 'error message', '错误提示信息', 'n.', 'The text shown or logged to describe what went wrong.', 'The error message didn''t say much, so I had to check the logs for more detail.', '错误提示信息没说太多，所以我不得不去查日志找更多细节。', ARRAY['debugging', 'troubleshooting']::text[], null, null, 141, true),
  ('dev-log-aggregation', 'developer', 'log aggregation', '日志聚合', 'n.', 'Collecting logs from many sources into a single searchable system.', 'Log aggregation across all services made it much faster to trace this request.', '把所有服务的日志聚合到一起，让追踪这个请求快了很多。', ARRAY['debugging', 'troubleshooting']::text[], null, null, 142, true),
  ('dev-verbose-logging', 'developer', 'verbose logging', '详细日志', 'n.', 'Logging that records much more detail than usual, often enabled temporarily to debug an issue.', 'Turn on verbose logging before you try to reproduce the issue again.', '在再次尝试复现这个问题之前，先打开详细日志。', ARRAY['debugging', 'troubleshooting']::text[], null, null, 143, true),
  ('dev-sanity-check', 'developer', 'sanity check', '基本合理性检查', 'n.', 'A quick, basic test to confirm something is working roughly as expected before deeper investigation.', 'Run a quick sanity check on the response before diving into the full test suite.', '在深入跑完整测试套件之前，先对返回结果做一个基本合理性检查。', ARRAY['debugging', 'troubleshooting']::text[], null, null, 144, true),
  ('dev-regression-bug', 'developer', 'regression bug', '回归性 bug', 'n.', 'A bug that reappears in previously working functionality after a code change.', 'The last deployment introduced a regression bug in the checkout flow.', '上一次部署在结算流程里引入了一个回归性 bug。', ARRAY['debugging', 'troubleshooting']::text[], null, null, 145, true),
  ('dev-flaky-test', 'developer', 'flaky test', '不稳定的测试', 'n.', 'A test that sometimes passes and sometimes fails without any code changes.', 'We quarantined the flaky test so it stops blocking unrelated pull requests.', '我们把这个不稳定的测试隔离了出来，避免它继续阻塞其他无关的拉取请求。', ARRAY['debugging', 'troubleshooting']::text[], null, null, 146, true),
  ('dev-edge-case-handling', 'developer', 'edge case handling', '边界情况处理', 'n.', 'Code written to correctly handle unusual or extreme inputs that fall outside typical usage.', 'Missing edge case handling for empty input was what caused this crash.', '正是缺少对空输入的边界情况处理，才导致了这次崩溃。', ARRAY['debugging', 'troubleshooting']::text[], null, null, 147, true),
  ('dev-troubleshoot', 'developer', 'troubleshoot', '排查故障', 'v.', 'To systematically identify and resolve the cause of a problem.', 'It took two engineers a full day to troubleshoot the intermittent connection issue.', '两名工程师花了整整一天时间才排查出这个间歇性的连接问题。', ARRAY['debugging', 'troubleshooting']::text[], null, null, 148, true),
  ('dev-workaround', 'developer', 'workaround', '临时解决方案', 'n.', 'A temporary way to avoid a problem without actually fixing its underlying cause.', 'We shipped a workaround for now and filed a ticket to fix it properly later.', '我们先上线了一个临时解决方案，并记录了一个工单来后续彻底修复。', ARRAY['debugging', 'troubleshooting']::text[], null, null, 149, true),
  ('dev-hotpatch', 'developer', 'hotpatch', '热补丁', 'n.', 'A fix applied to running software without requiring a full restart or redeployment.', 'We pushed a hotpatch to stop the errors while the real fix was still in review.', '在正式修复方案还在审查时，我们先推送了一个热补丁来止住错误。', ARRAY['debugging', 'troubleshooting']::text[], null, null, 150, true),
  ('dev-core-dump', 'developer', 'core dump', '核心转储', 'n.', 'A snapshot of a program''s memory taken at the moment it crashed, used for post-mortem debugging.', 'We analyzed the core dump to figure out exactly where the process had crashed.', '我们分析了核心转储，才弄清楚这个进程究竟是在哪里崩溃的。', ARRAY['debugging', 'troubleshooting']::text[], null, null, 151, true),
  ('dev-watch-expression', 'developer', 'watch expression', '监视表达式', 'n.', 'A value tracked in a debugger so its changes can be observed as the program runs.', 'I added a watch expression on the counter to see exactly when it went negative.', '我给计数器加了一个监视表达式，来查看它究竟是什么时候变成负数的。', ARRAY['debugging', 'troubleshooting']::text[], null, null, 152, true),
  ('dev-step-through-code', 'developer', 'step through code', '单步调试代码', 'phr.', 'To execute a program one line at a time in a debugger to observe its behavior.', 'Step through the code line by line to see exactly where the value changes.', '单步调试代码，逐行查看这个值究竟是在哪里发生变化的。', ARRAY['debugging', 'troubleshooting']::text[], null, null, 153, true),
  ('dev-silent-failure', 'developer', 'silent failure', '静默失败', 'n.', 'A failure that occurs without producing any visible error, log, or notification.', 'The retry logic was swallowing errors, causing a silent failure that no one noticed for weeks.', '重试逻辑吞掉了错误，造成了一次静默失败，好几周都没人发现。', ARRAY['debugging', 'troubleshooting']::text[], null, null, 154, true),
  ('dev-timeout-error', 'developer', 'timeout error', '超时错误', 'n.', 'An error that occurs when an operation takes longer than the allowed time limit.', 'The upload keeps failing with a timeout error on slower connections.', '在网速较慢的情况下，这次上传一直报超时错误。', ARRAY['debugging', 'troubleshooting']::text[], null, null, 155, true),
  ('dev-off-by-one-error', 'developer', 'off-by-one error', '差一错误', 'n.', 'A common bug caused by a loop or index boundary that is one step too high or too low.', 'It turned out to be a classic off-by-one error in the loop''s stopping condition.', '最后发现是循环终止条件里一个典型的差一错误。', ARRAY['debugging', 'troubleshooting']::text[], null, null, 156, true),
  ('dev-print-debugging', 'developer', 'print debugging', '打印调试法', 'n.', 'A debugging technique that inserts print or log statements to inspect a program''s state.', 'Sometimes print debugging is faster than setting up a full debugger session.', '有时候打印调试法比配置一整套调试器会话还要快。', ARRAY['debugging', 'troubleshooting']::text[], null, null, 157, true),
  ('dev-unit-test', 'developer', 'unit test', '单元测试', 'n.', 'A test that verifies a single, isolated piece of code, such as one function.', 'Every new function should ship with at least one unit test.', '每个新函数至少应该配一个单元测试。', ARRAY['testing', 'qa']::text[], null, null, 158, true),
  ('dev-integration-test', 'developer', 'integration test', '集成测试', 'n.', 'A test that verifies multiple components work correctly together.', 'The integration test caught a mismatch between the API and the database layer.', '这个集成测试发现了 API 层和数据库层之间的一个不匹配问题。', ARRAY['testing', 'qa']::text[], null, null, 159, true),
  ('dev-end-to-end-test', 'developer', 'end-to-end test', '端到端测试', 'n.', 'A test that verifies a complete user flow through the whole system, from start to finish.', 'The end-to-end test simulates a full checkout, from adding an item to receiving the confirmation email.', '这个端到端测试模拟了完整的结算流程，从添加商品到收到确认邮件。', ARRAY['testing', 'qa']::text[], null, null, 160, true),
  ('dev-test-coverage', 'developer', 'test coverage', '测试覆盖率', 'n.', 'A measure of how much of the codebase is exercised by automated tests.', 'Test coverage for this module dropped after the last refactor.', '上次重构之后，这个模块的测试覆盖率下降了。', ARRAY['testing', 'qa']::text[], null, null, 161, true),
  ('dev-mock-object', 'developer', 'mock object', '模拟对象', 'n.', 'A fake object that simulates the behavior of a real dependency for testing purposes.', 'We used a mock object for the payment gateway so tests don''t hit the real service.', '我们对支付网关用了一个模拟对象，这样测试就不会真的调用外部服务。', ARRAY['testing', 'qa']::text[], null, null, 162, true),
  ('dev-stub', 'developer', 'stub', '桩（测试替身）', 'n.', 'A minimal, hardcoded stand-in implementation that returns fixed data instead of running real logic.', 'We wrote a stub for the third-party API so tests run without any network access.', '我们为这个第三方 API 写了一个桩，这样测试运行时就不需要网络访问了。', ARRAY['testing', 'qa']::text[], null, null, 163, true),
  ('dev-test-case', 'developer', 'test case', '测试用例', 'n.', 'A single set of inputs, actions, and expected results used to verify a specific behavior.', 'Add a test case for what happens when the input list is empty.', '加一个测试用例，覆盖输入列表为空的情况。', ARRAY['testing', 'qa']::text[], null, null, 164, true),
  ('dev-test-suite', 'developer', 'test suite', '测试套件', 'n.', 'A collection of related test cases grouped together and typically run as a unit.', 'The whole test suite now runs in under three minutes on CI.', '现在整个测试套件在 CI 上运行不到三分钟。', ARRAY['testing', 'qa']::text[], null, null, 165, true),
  ('dev-assertion', 'developer', 'assertion', '断言', 'n.', 'A statement in a test that checks whether an actual result matches the expected one.', 'The assertion failed because the response returned an extra field.', '这个断言失败了，因为返回结果多了一个字段。', ARRAY['testing', 'qa']::text[], null, null, 166, true),
  ('dev-regression-testing', 'developer', 'regression testing', '回归测试', 'n.', 'Re-running existing tests after a change to confirm previously working functionality still works.', 'Regression testing is run automatically before every release.', '每次发布之前都会自动进行回归测试。', ARRAY['testing', 'qa']::text[], null, null, 167, true),
  ('dev-test-driven-development', 'developer', 'test-driven development', '测试驱动开发', 'n.', 'A development practice where a failing test is written before the code that makes it pass.', 'With test-driven development, we wrote the failing test first, then implemented the feature.', '按照测试驱动开发的方式，我们先写了一个会失败的测试，然后再实现这个功能。', ARRAY['testing', 'qa']::text[], null, null, 168, true),
  ('dev-continuous-testing', 'developer', 'continuous testing', '持续测试', 'n.', 'Automatically running tests as part of the development pipeline to get fast feedback.', 'Continuous testing gives us feedback within minutes of pushing a commit.', '持续测试让我们在推送提交后几分钟内就能拿到反馈。', ARRAY['testing', 'qa']::text[], null, null, 169, true),
  ('dev-smoke-test', 'developer', 'smoke test', '冒烟测试', 'n.', 'A quick test that checks whether the most critical functionality works at a basic level.', 'Run the smoke test right after deployment to confirm the service is up.', '部署完成后立刻跑一次冒烟测试，确认服务已经正常启动。', ARRAY['testing', 'qa']::text[], null, null, 170, true),
  ('dev-acceptance-criteria', 'developer', 'acceptance criteria', '验收标准', 'n.', 'The conditions a feature must satisfy to be considered complete and accepted.', 'This ticket won''t be closed until it meets all the acceptance criteria.', '这个工单要满足所有验收标准才能关闭。', ARRAY['testing', 'qa']::text[], null, null, 171, true),
  ('dev-quality-assurance', 'developer', 'quality assurance', '质量保证', 'n.', 'The set of activities and processes aimed at ensuring a product meets quality standards.', 'Quality assurance flagged three issues before this build could be released.', '质量保证团队在这个版本发布前标记出了三个问题。', ARRAY['testing', 'qa']::text[], null, null, 172, true),
  ('dev-test-fixture', 'developer', 'test fixture', '测试夹具', 'n.', 'A fixed, known state or set of data set up before a test runs so results are consistent.', 'The test fixture seeds the database with three sample users before each test.', '这个测试夹具会在每次测试前向数据库写入三个示例用户。', ARRAY['testing', 'qa']::text[], null, null, 173, true),
  ('dev-coverage-report', 'developer', 'coverage report', '覆盖率报告', 'n.', 'A generated summary showing which lines or branches of code were executed by tests.', 'The coverage report highlighted a whole error-handling branch that was never tested.', '覆盖率报告标出了一整段从未被测试覆盖到的错误处理分支。', ARRAY['testing', 'qa']::text[], null, null, 174, true),
  ('dev-black-box-testing', 'developer', 'black-box testing', '黑盒测试', 'n.', 'Testing that verifies behavior based only on inputs and outputs, without knowledge of internal implementation.', 'We did black-box testing on the API using only the public documentation.', '我们只根据公开文档对这个 API 做了黑盒测试。', ARRAY['testing', 'qa']::text[], null, null, 175, true),
  ('dev-white-box-testing', 'developer', 'white-box testing', '白盒测试', 'n.', 'Testing designed with full knowledge of the internal code structure and logic.', 'White-box testing let us target the specific branches that were hardest to reach.', '白盒测试让我们能够专门针对那些最难触及的代码分支进行测试。', ARRAY['testing', 'qa']::text[], null, null, 176, true),
  ('dev-load-testing', 'developer', 'load testing', '负载测试', 'n.', 'Testing how a system performs under an expected or peak level of demand.', 'Load testing revealed the service starts timing out past five thousand concurrent users.', '负载测试发现，一旦并发用户超过五千，这个服务就会开始超时。', ARRAY['testing', 'qa']::text[], null, null, 177, true),
  ('dev-test-automation', 'developer', 'test automation', '测试自动化', 'n.', 'Using tools and scripts to run tests automatically instead of manually.', 'Test automation freed up the QA team to focus on exploratory testing instead.', '测试自动化让 QA 团队能把精力放到探索性测试上。', ARRAY['testing', 'qa']::text[], null, null, 178, true),
  ('dev-bug-tracker', 'developer', 'bug tracker', '缺陷跟踪系统', 'n.', 'A system used to record, prioritize, and track the status of reported bugs.', 'File the issue in the bug tracker so it doesn''t get forgotten.', '把这个问题记录到缺陷跟踪系统里，避免它被遗忘。', ARRAY['testing', 'qa']::text[], null, null, 179, true),
  ('dev-false-positive', 'developer', 'false positive', '误报（假阳性）', 'n.', 'A test or alert that incorrectly reports a problem when none actually exists.', 'That security alert turned out to be a false positive.', '那个安全告警最后证实是一次误报。', ARRAY['testing', 'qa']::text[], null, null, 180, true),
  ('dev-false-negative', 'developer', 'false negative', '漏报（假阴性）', 'n.', 'A test that incorrectly reports no problem when one actually exists.', 'The weak test suite produced a false negative and let a real bug through.', '测试套件覆盖不够，产生了一次漏报，导致一个真实的 bug 被放过去了。', ARRAY['testing', 'qa']::text[], null, null, 181, true),
  ('dev-staging-environment', 'developer', 'staging environment', '预发布环境', 'n.', 'An environment that mirrors production, used to verify changes before they go live.', 'Always verify the migration in the staging environment before running it in production.', '在生产环境执行这次迁移之前，一定要先在预发布环境验证。', ARRAY['testing', 'qa']::text[], null, null, 182, true),
  ('dev-qa-sign-off', 'developer', 'QA sign-off', 'QA 验收确认', 'n.', 'Formal approval from the quality assurance team that a build meets the required quality bar.', 'We can''t release until we get QA sign-off on this build.', '在拿到这个版本的 QA 验收确认之前，我们不能发布。', ARRAY['testing', 'qa']::text[], null, 'Q A sign-off', 183, true),
  ('dev-manual-testing', 'developer', 'manual testing', '手动测试', 'n.', 'Testing performed by a person directly interacting with the software, without automated scripts.', 'Manual testing caught a layout issue that our automated tests never checked for.', '手动测试发现了一个自动化测试从未检查过的布局问题。', ARRAY['testing', 'qa']::text[], null, null, 184, true),
  ('dev-test-plan', 'developer', 'test plan', '测试计划', 'n.', 'A document that outlines the scope, approach, and schedule for testing a feature or release.', 'The test plan lists every device and OS version we need to verify before launch.', '这份测试计划列出了发布前需要验证的每一款设备和操作系统版本。', ARRAY['testing', 'qa']::text[], null, null, 185, true),
  ('dev-test-double', 'developer', 'test double', '测试替身', 'n.', 'A general term for any fake object — such as a mock, stub, or fake — used in place of a real dependency during testing.', 'We use a test double for the email service so tests never send real emails.', '我们对邮件服务用了一个测试替身，这样测试就不会真的发送邮件。', ARRAY['testing', 'qa']::text[], null, null, 186, true),
  ('dev-api', 'developer', 'API', '应用程序接口', 'abbr.', 'A defined set of rules that lets one piece of software communicate with another.', 'The mobile app talks to the backend through a REST API.', '这个移动端应用通过一个 REST API 和后端通信。', ARRAY['api', 'networking']::text[], null, 'A P I', 187, true),
  ('dev-rest-api', 'developer', 'REST API', 'REST 风格接口', 'n.', 'An API that follows REST principles, using standard HTTP methods to operate on resources.', 'We exposed the inventory system as a REST API so other teams could integrate with it.', '我们把库存系统以 REST 接口的形式对外暴露，方便其他团队接入。', ARRAY['api', 'networking']::text[], null, 'rest A P I', 188, true),
  ('dev-endpoint', 'developer', 'endpoint', '接口端点', 'n.', 'A specific URL where an API can be accessed to perform an operation.', 'Add a new endpoint for fetching a user''s order history.', '新增一个接口端点，用来获取用户的订单历史。', ARRAY['api', 'networking']::text[], null, null, 189, true),
  ('dev-http-request', 'developer', 'HTTP request', 'HTTP 请求', 'n.', 'A message sent from a client to a server asking it to perform an action.', 'Every HTTP request to this endpoint must include an authorization header.', '发往这个接口的每一个 HTTP 请求都必须带上认证请求头。', ARRAY['api', 'networking']::text[], null, 'H T T P request', 190, true),
  ('dev-http-response', 'developer', 'HTTP response', 'HTTP 响应', 'n.', 'The message a server sends back after processing an HTTP request.', 'The HTTP response includes the new resource''s id in its body.', '这个 HTTP 响应的正文里包含了新资源的 id。', ARRAY['api', 'networking']::text[], null, 'H T T P response', 191, true),
  ('dev-status-code', 'developer', 'status code', '状态码', 'n.', 'A three-digit number in an HTTP response that indicates the outcome of a request.', 'A 404 status code means the requested resource wasn''t found.', '404 状态码表示请求的资源没有找到。', ARRAY['api', 'networking']::text[], null, null, 192, true),
  ('dev-request-header', 'developer', 'request header', '请求头', 'n.', 'Metadata sent with an HTTP request, such as content type or authorization information.', 'The server rejects the request if the request header is missing the API key.', '如果请求头里缺少 API 密钥，服务器就会拒绝这次请求。', ARRAY['api', 'networking']::text[], null, null, 193, true),
  ('dev-payload', 'developer', 'payload', '负载（消息主体数据）', 'n.', 'The actual data being transmitted in a request, response, or message.', 'Keep the webhook payload small so it can be processed quickly.', '把这个 webhook 的负载保持得小一些，这样处理起来会更快。', ARRAY['api', 'networking']::text[], null, null, 194, true),
  ('dev-json', 'developer', 'JSON', 'JSON 数据格式', 'n.', 'A lightweight, text-based data format commonly used to exchange data between systems.', 'The API returns the result as JSON.', '这个 API 以 JSON 格式返回结果。', ARRAY['api', 'networking']::text[], null, null, 195, true),
  ('dev-query-parameter', 'developer', 'query parameter', '查询参数', 'n.', 'A key-value pair appended to a URL, typically used to filter or configure a request.', 'Add a query parameter to control how many results are returned per page.', '加一个查询参数来控制每页返回多少条结果。', ARRAY['api', 'networking']::text[], null, null, 196, true),
  ('dev-path-parameter', 'developer', 'path parameter', '路径参数', 'n.', 'A variable segment embedded directly in a URL''s path, such as an id.', 'The user id is passed as a path parameter, not a query parameter.', '用户 id 是作为路径参数传递的，而不是查询参数。', ARRAY['api', 'networking']::text[], null, null, 197, true),
  ('dev-authentication', 'developer', 'authentication', '身份验证', 'n.', 'The process of confirming that a user or system is who they claim to be.', 'Authentication failed because the token had already expired.', '身份验证失败了，因为这个令牌已经过期。', ARRAY['api', 'security']::text[], null, null, 198, true),
  ('dev-authorization', 'developer', 'authorization', '权限授权', 'n.', 'The process of determining what an authenticated user or system is allowed to do.', 'The user was authenticated but the request still failed authorization.', '这个用户虽然通过了身份验证，但这次请求在权限授权上没有通过。', ARRAY['api', 'security']::text[], null, null, 199, true),
  ('dev-api-key', 'developer', 'API key', 'API 密钥', 'n.', 'A unique identifier used to authenticate requests to an API.', 'Never hardcode an API key directly into client-side code.', '永远不要把 API 密钥直接硬编码进客户端代码里。', ARRAY['api', 'security']::text[], null, 'A P I key', 200, true),
  ('dev-rate-limiting', 'developer', 'rate limiting', '速率限制', 'n.', 'Restricting how many requests a client can make within a given time period.', 'We added rate limiting to stop a single client from overwhelming the API.', '我们加上了速率限制，防止单个客户端把这个 API 打垮。', ARRAY['api', 'networking']::text[], null, null, 201, true),
  ('dev-webhook', 'developer', 'webhook', 'Webhook（事件回调）', 'n.', 'An HTTP callback that automatically sends data to another system when a specific event occurs.', 'The payment provider sends a webhook whenever a transaction completes.', '支付服务商在每笔交易完成时都会发送一个 webhook。', ARRAY['api', 'networking']::text[], null, null, 202, true),
  ('dev-graphql', 'developer', 'GraphQL', 'GraphQL 查询语言', 'n.', 'A query language for APIs that lets clients request exactly the data fields they need.', 'We migrated the dashboard to GraphQL so it stops over-fetching unused fields.', '我们把仪表盘迁移到了 GraphQL，避免再过度获取用不到的字段。', ARRAY['api', 'networking']::text[], null, null, 203, true),
  ('dev-idempotent', 'developer', 'idempotent', '幂等的', 'adj.', 'Describing an operation that produces the same result no matter how many times it is repeated.', 'Make sure the retry logic only calls idempotent endpoints to avoid duplicate charges.', '确保重试逻辑只调用幂等的接口，以避免重复扣费。', ARRAY['api', 'networking']::text[], null, null, 204, true),
  ('dev-latency', 'developer', 'latency', '延迟', 'n.', 'The time delay between sending a request and receiving a response.', 'Moving the server closer to users cut the average latency in half.', '把服务器部署得离用户更近，把平均延迟降低了一半。', ARRAY['api', 'networking']::text[], null, null, 205, true),
  ('dev-request-timeout', 'developer', 'request timeout', '请求超时', 'n.', 'A limit on how long a client waits for a response before giving up.', 'We increased the request timeout for the report-generation endpoint.', '我们调高了报表生成接口的请求超时时间。', ARRAY['api', 'networking']::text[], null, null, 206, true),
  ('dev-cors', 'developer', 'CORS', '跨域资源共享', 'abbr.', 'A browser security mechanism that controls whether a web page can request resources from another domain.', 'The request was blocked by a CORS error because the origin wasn''t allowed.', '这次请求因为来源域名不在允许列表里，被 CORS 错误拦截了。', ARRAY['api', 'networking']::text[], null, 'C O R S', 207, true),
  ('dev-sdk', 'developer', 'SDK', '软件开发工具包', 'abbr.', 'A collection of tools, libraries, and documentation used to build applications for a specific platform.', 'Install the payment provider''s SDK instead of calling the API directly.', '直接安装这个支付服务商的 SDK，而不是自己调用底层 API。', ARRAY['api', 'networking']::text[], null, 'S D K', 208, true),
  ('dev-api-versioning', 'developer', 'API versioning', 'API 版本管理', 'n.', 'The practice of managing changes to an API over time without breaking existing clients.', 'API versioning let us change the response format without breaking older mobile clients.', 'API 版本管理让我们能够改变响应格式，同时不影响老版本的移动端客户端。', ARRAY['api', 'networking']::text[], null, 'A P I versioning', 209, true),
  ('dev-request-body', 'developer', 'request body', '请求体', 'n.', 'The data sent along with an HTTP request, typically used with POST or PUT methods.', 'The server returned a 400 because the request body was missing a required field.', '服务器返回了 400，因为请求体缺少一个必填字段。', ARRAY['api', 'networking']::text[], null, null, 210, true),
  ('dev-restful-design', 'developer', 'RESTful design', 'RESTful 设计风格', 'n.', 'An API design approach that models resources with URLs and standard HTTP methods.', 'Following RESTful design, we use a POST to /orders to create a new order.', '按照 RESTful 设计风格，我们用 POST 请求 /orders 来创建新订单。', ARRAY['api', 'networking']::text[], null, null, 211, true),
  ('dev-grpc', 'developer', 'gRPC', 'gRPC 远程调用框架', 'n.', 'A high-performance remote procedure call framework that uses protocol buffers for communication.', 'Internal services communicate over gRPC for lower latency than REST.', '内部服务之间使用 gRPC 通信，延迟比 REST 更低。', ARRAY['api', 'networking']::text[], null, 'G R P C', 212, true),
  ('dev-dns', 'developer', 'DNS', '域名系统', 'abbr.', 'The system that translates human-readable domain names into IP addresses.', 'The outage was caused by a DNS misconfiguration, not the application itself.', '这次故障是 DNS 配置错误导致的，而不是应用本身的问题。', ARRAY['api', 'networking']::text[], null, 'D N S', 213, true),
  ('dev-load-balancer', 'developer', 'load balancer', '负载均衡器', 'n.', 'A component that distributes incoming traffic across multiple servers.', 'The load balancer routes traffic away from any instance that fails its health check.', '负载均衡器会把流量从任何健康检查失败的实例上引开。', ARRAY['api', 'networking']::text[], null, null, 214, true),
  ('dev-api-documentation', 'developer', 'API documentation', 'API 文档', 'n.', 'Reference material that describes how to use an API, including endpoints, parameters, and responses.', 'The API documentation includes example requests for every endpoint.', '这份 API 文档为每个接口都提供了示例请求。', ARRAY['api', 'networking']::text[], null, 'A P I documentation', 215, true),
  ('dev-backend', 'developer', 'backend', '后端', 'n.', 'The server-side part of an application that handles logic, data, and infrastructure.', 'The backend validates the order before it ever reaches the database.', '后端会在订单进入数据库之前先对其进行校验。', ARRAY['backend', 'distributed-systems']::text[], null, null, 216, true),
  ('dev-server', 'developer', 'server', '服务器', 'n.', 'A program or machine that provides resources or services to other programs over a network.', 'The server restarted automatically after the memory limit was reached.', '达到内存上限后，服务器自动重启了。', ARRAY['backend', 'distributed-systems']::text[], null, null, 217, true),
  ('dev-microservice', 'developer', 'microservice', '微服务', 'n.', 'A small, independently deployable service that handles a single business capability.', 'We split the billing logic out into its own microservice.', '我们把计费逻辑拆分成了一个独立的微服务。', ARRAY['backend', 'distributed-systems']::text[], null, null, 218, true),
  ('dev-monolith', 'developer', 'monolith', '单体应用', 'n.', 'An application built as a single, tightly coupled unit rather than separate services.', 'The monolith became hard to deploy safely once ten teams were shipping to it at once.', '当十个团队同时向这个单体应用发布代码时，安全部署就变得很困难了。', ARRAY['backend', 'distributed-systems']::text[], null, null, 219, true),
  ('dev-service-discovery', 'developer', 'service discovery', '服务发现', 'n.', 'A mechanism that lets services automatically find the network location of other services.', 'Service discovery lets the API gateway find healthy instances without hardcoded addresses.', '服务发现让 API 网关不需要硬编码地址，就能找到健康的服务实例。', ARRAY['backend', 'distributed-systems']::text[], null, null, 220, true),
  ('dev-distributed-system', 'developer', 'distributed system', '分布式系统', 'n.', 'A system composed of multiple independent machines that work together and communicate over a network.', 'Debugging a distributed system is harder because a failure could be in any one of dozens of services.', '调试分布式系统更困难，因为故障可能出现在几十个服务中的任何一个。', ARRAY['backend', 'distributed-systems']::text[], null, null, 221, true),
  ('dev-horizontal-scaling', 'developer', 'horizontal scaling', '水平扩展', 'n.', 'Increasing capacity by adding more machines or instances rather than upgrading one machine.', 'Horizontal scaling let us handle the traffic spike by simply adding more instances.', '水平扩展让我们只需增加更多实例，就能应对这次流量高峰。', ARRAY['backend', 'distributed-systems']::text[], null, null, 222, true),
  ('dev-vertical-scaling', 'developer', 'vertical scaling', '垂直扩展', 'n.', 'Increasing capacity by upgrading a single machine''s resources, such as CPU or memory.', 'Vertical scaling bought us time, but eventually we needed a real architecture change.', '垂直扩展为我们争取了一些时间，但最终还是需要真正的架构调整。', ARRAY['backend', 'distributed-systems']::text[], null, null, 223, true),
  ('dev-fault-tolerance', 'developer', 'fault tolerance', '容错能力', 'n.', 'A system''s ability to keep operating correctly even when part of it fails.', 'The system''s fault tolerance meant losing one server didn''t affect users at all.', '这个系统的容错能力使得丢失一台服务器完全不会影响用户。', ARRAY['backend', 'distributed-systems']::text[], null, null, 224, true),
  ('dev-eventual-consistency', 'developer', 'eventual consistency', '最终一致性', 'n.', 'A consistency model in which all replicas of data converge to the same value, but not necessarily instantly.', 'We chose eventual consistency here to keep write latency low across regions.', '我们在这里选择了最终一致性，以保持跨地区写入的低延迟。', ARRAY['backend', 'distributed-systems']::text[], null, null, 225, true),
  ('dev-consensus-algorithm', 'developer', 'consensus algorithm', '共识算法', 'n.', 'An algorithm that lets distributed nodes agree on a single value even if some nodes fail.', 'The cluster uses a consensus algorithm to elect a new leader when one node goes down.', '这个集群用共识算法在某个节点宕机时选出新的主节点。', ARRAY['backend', 'distributed-systems']::text[], null, null, 226, true),
  ('dev-sharding', 'developer', 'sharding', '分片', 'n.', 'Splitting a dataset across multiple databases or servers to spread load and storage.', 'We introduced sharding once a single database could no longer hold all the user data.', '当单个数据库再也装不下所有用户数据时，我们引入了分片。', ARRAY['backend', 'distributed-systems']::text[], null, null, 227, true),
  ('dev-replication', 'developer', 'replication', '数据复制', 'n.', 'Copying data across multiple nodes to improve availability and read performance.', 'Replication across three regions keeps the service running even if one region goes offline.', '跨三个地区的数据复制使得即便一个地区离线，服务也能继续运行。', ARRAY['backend', 'distributed-systems']::text[], null, null, 228, true),
  ('dev-failover', 'developer', 'failover', '故障转移', 'n.', 'Automatically switching to a backup system when the primary one fails.', 'Failover to the standby database kicked in within seconds of the primary going down.', '主数据库宕机后几秒钟内就触发了向备用数据库的故障转移。', ARRAY['backend', 'distributed-systems']::text[], null, null, 229, true),
  ('dev-circuit-breaker', 'developer', 'circuit breaker', '熔断器', 'n.', 'A pattern that stops calling a failing service temporarily to prevent cascading failures.', 'The circuit breaker tripped after the downstream service started timing out repeatedly.', '在下游服务反复超时之后，熔断器被触发了。', ARRAY['backend', 'distributed-systems']::text[], null, null, 230, true),
  ('dev-asynchronous-processing', 'developer', 'asynchronous processing', '异步处理', 'n.', 'Handling a task without blocking the caller, often by running it in the background.', 'We moved email sending to asynchronous processing so it doesn''t slow down the request.', '我们把发送邮件改成了异步处理，这样就不会拖慢这次请求。', ARRAY['backend', 'distributed-systems']::text[], null, null, 231, true),
  ('dev-synchronous-call', 'developer', 'synchronous call', '同步调用', 'n.', 'A call that blocks and waits for a response before the caller continues.', 'A synchronous call to the pricing service was adding two seconds to every checkout.', '每次对定价服务的同步调用都会给结算流程增加两秒钟延迟。', ARRAY['backend', 'distributed-systems']::text[], null, null, 232, true),
  ('dev-middleware', 'developer', 'middleware', '中间件', 'n.', 'Software that sits between components, often handling cross-cutting concerns like logging or authentication.', 'We added a middleware that logs every incoming request before it reaches the handler.', '我们加了一个中间件，在请求到达处理函数之前先记录日志。', ARRAY['backend', 'distributed-systems']::text[], null, null, 233, true),
  ('dev-service-orchestration', 'developer', 'service orchestration', '服务编排', 'n.', 'Coordinating multiple services to work together to complete a larger business process.', 'Service orchestration ensures the payment, inventory, and shipping steps run in the right order.', '服务编排确保支付、库存和发货这几个步骤按正确的顺序执行。', ARRAY['backend', 'distributed-systems']::text[], null, null, 234, true),
  ('dev-service-mesh', 'developer', 'service mesh', '服务网格', 'n.', 'An infrastructure layer that manages service-to-service communication, including routing, retries, and security.', 'The service mesh handles retries and mutual TLS so individual services don''t have to.', '服务网格统一处理重试和双向 TLS，各个服务本身不需要再自己实现。', ARRAY['backend', 'distributed-systems']::text[], null, null, 235, true),
  ('dev-api-gateway', 'developer', 'API gateway', 'API 网关', 'n.', 'A single entry point that routes client requests to the appropriate backend services.', 'The API gateway handles authentication once so individual services don''t have to.', 'API 网关统一处理身份验证，各个服务就不需要重复实现了。', ARRAY['backend', 'distributed-systems']::text[], null, 'A P I gateway', 236, true),
  ('dev-message-broker', 'developer', 'message broker', '消息代理', 'n.', 'A system that routes messages between producers and consumers, decoupling them from each other.', 'The message broker buffers events so a slow consumer doesn''t block the producer.', '消息代理会缓冲事件，避免消费者处理慢时阻塞生产者。', ARRAY['backend', 'distributed-systems']::text[], null, null, 237, true),
  ('dev-event-driven-architecture', 'developer', 'event-driven architecture', '事件驱动架构', 'n.', 'An architecture where services communicate by producing and reacting to events rather than direct calls.', 'We adopted an event-driven architecture so new services can react to order events without changing the checkout code.', '我们采用了事件驱动架构，这样新服务就能响应订单事件，而无需改动结算代码。', ARRAY['backend', 'distributed-systems']::text[], null, null, 238, true),
  ('dev-stateless-service', 'developer', 'stateless service', '无状态服务', 'n.', 'A service that does not store any client session data between requests, making it easy to scale.', 'Because it''s a stateless service, we can add or remove instances at any time.', '因为这是一个无状态服务，我们随时都可以增加或减少实例数量。', ARRAY['backend', 'distributed-systems']::text[], null, null, 239, true),
  ('dev-idempotency-key', 'developer', 'idempotency key', '幂等键', 'n.', 'A unique value sent with a request so retries can be safely detected and deduplicated.', 'Clients must include an idempotency key so a retried payment isn''t charged twice.', '客户端必须带上一个幂等键，避免重试的支付请求被重复扣费。', ARRAY['backend', 'distributed-systems']::text[], null, null, 240, true),
  ('dev-throttling', 'developer', 'throttling', '限流', 'n.', 'Deliberately slowing down or limiting the rate of requests a system processes.', 'Throttling kicked in and started rejecting requests once traffic doubled.', '流量翻倍之后，限流机制启动，开始拒绝部分请求。', ARRAY['backend', 'distributed-systems']::text[], null, null, 241, true),
  ('dev-backpressure', 'developer', 'backpressure', '背压', 'n.', 'A mechanism where a slower consumer signals a faster producer to slow down, preventing overload.', 'Without backpressure, the fast producer overwhelmed the slow consumer''s queue.', '没有背压机制的话，速度更快的生产者会压垮消费者的队列。', ARRAY['backend', 'distributed-systems']::text[], null, null, 242, true),
  ('dev-single-point-of-failure', 'developer', 'single point of failure', '单点故障', 'n.', 'A component whose failure would bring down the entire system.', 'The shared database was a single point of failure until we added a replica.', '在我们加上副本之前，这个共享数据库一直是个单点故障。', ARRAY['backend', 'distributed-systems']::text[], null, null, 243, true),
  ('dev-connection-timeout', 'developer', 'connection timeout', '连接超时', 'n.', 'The maximum time a client waits while trying to establish a connection before giving up.', 'We lowered the connection timeout so a dead node fails fast instead of hanging requests.', '我们调低了连接超时时间，让失效节点能快速失败，而不是让请求一直挂起。', ARRAY['backend', 'distributed-systems']::text[], null, null, 244, true),
  ('dev-database', 'developer', 'database', '数据库', 'n.', 'An organized collection of data that can be stored, queried, and updated.', 'We ran the migration against a copy of the production database first.', '我们先在生产数据库的一个副本上执行了这次迁移。', ARRAY['database', 'caching']::text[], null, null, 245, true),
  ('dev-sql', 'developer', 'SQL', '结构化查询语言', 'abbr.', 'A standard language used to query and manipulate data in a relational database.', 'This SQL query joins three tables to build the report.', '这条 SQL 查询语句连接了三张表来生成报表。', ARRAY['database', 'caching']::text[], null, 'S Q L', 246, true),
  ('dev-nosql', 'developer', 'NoSQL', '非关系型数据库', 'n.', 'A category of databases that store data in formats other than traditional relational tables.', 'We chose a NoSQL database because the shape of our data changes frequently.', '我们选择了非关系型数据库，因为我们数据的结构经常变化。', ARRAY['database', 'caching']::text[], null, 'no S Q L', 247, true),
  ('dev-schema', 'developer', 'schema', '数据模式；表结构', 'n.', 'The formal structure that defines the tables, fields, and relationships in a database.', 'Adding a new column requires a schema change and a migration.', '新增一列需要修改数据模式并执行迁移。', ARRAY['database', 'caching']::text[], null, null, 248, true),
  ('dev-primary-key', 'developer', 'primary key', '主键', 'n.', 'A column or set of columns that uniquely identifies each row in a table.', 'Every table in this schema uses a UUID as its primary key.', '这个数据模式里的每张表都用 UUID 作为主键。', ARRAY['database', 'caching']::text[], null, null, 249, true),
  ('dev-foreign-key', 'developer', 'foreign key', '外键', 'n.', 'A column that references the primary key of another table, establishing a relationship between them.', 'The orders table has a foreign key pointing back to the customers table.', '订单表中有一个外键指向客户表。', ARRAY['database', 'caching']::text[], null, null, 250, true),
  ('dev-database-index', 'developer', 'database index', '数据库索引', 'n.', 'A data structure that speeds up lookups on a table at the cost of extra storage and write overhead.', 'Adding a database index on the email column made this query ten times faster.', '给 email 这一列加上数据库索引后，这个查询快了十倍。', ARRAY['database', 'caching']::text[], null, null, 251, true),
  ('dev-query-optimization', 'developer', 'query optimization', '查询优化', 'n.', 'The process of restructuring a database query to run faster or use fewer resources.', 'Query optimization brought this report''s runtime down from a minute to a few seconds.', '经过查询优化，这份报表的运行时间从一分钟缩短到了几秒钟。', ARRAY['database', 'caching']::text[], null, null, 252, true),
  ('dev-transaction', 'developer', 'transaction', '事务', 'n.', 'A group of database operations that either all succeed together or all fail together.', 'Wrap both updates in a single transaction so they never leave the data half-changed.', '把这两次更新放进同一个事务里，避免数据处于一半修改的中间状态。', ARRAY['database', 'caching']::text[], null, null, 253, true),
  ('dev-acid', 'developer', 'ACID', 'ACID 事务特性', 'abbr.', 'A set of guarantees — atomicity, consistency, isolation, and durability — that ensure reliable database transactions.', 'We picked a database with strong ACID guarantees for the payment ledger.', '我们为支付流水账选择了一个具有强 ACID 保证的数据库。', ARRAY['database', 'caching']::text[], null, null, 254, true),
  ('dev-normalization', 'developer', 'normalization', '范式化', 'n.', 'Structuring a database to reduce data redundancy by splitting it into related tables.', 'Normalization removed the duplicated address fields scattered across three tables.', '范式化去除了散落在三张表里的重复地址字段。', ARRAY['database', 'caching']::text[], null, null, 255, true),
  ('dev-denormalization', 'developer', 'denormalization', '反范式化', 'n.', 'Deliberately duplicating data across tables to improve read performance at the cost of redundancy.', 'We used denormalization on the reporting table to avoid expensive joins.', '我们对报表表做了反范式化处理，以避免昂贵的多表关联查询。', ARRAY['database', 'caching']::text[], null, null, 256, true),
  ('dev-cache', 'developer', 'cache', '缓存', 'n.', 'A temporary storage layer that keeps frequently accessed data close by for faster retrieval.', 'We put a cache in front of the database to absorb repeated identical queries.', '我们在数据库前加了一层缓存，用来承接重复的相同查询。', ARRAY['database', 'caching']::text[], null, null, 257, true),
  ('dev-cache-hit', 'developer', 'cache hit', '缓存命中', 'n.', 'A situation where requested data is found in the cache instead of the original source.', 'Ninety percent of requests result in a cache hit, so the database load stays low.', '九成的请求都能达到缓存命中，所以数据库的负载一直很低。', ARRAY['database', 'caching']::text[], null, null, 258, true),
  ('dev-cache-miss', 'developer', 'cache miss', '缓存未命中', 'n.', 'A situation where requested data is not found in the cache and must be fetched from the original source.', 'A cold cache means every request is a cache miss right after a deploy.', '缓存刚被清空时，部署后的每个请求都会是缓存未命中。', ARRAY['database', 'caching']::text[], null, null, 259, true),
  ('dev-cache-invalidation', 'developer', 'cache invalidation', '缓存失效', 'n.', 'The process of removing or updating stale cached data so it stays consistent with the source.', 'Cache invalidation bugs are why the user still saw their old profile picture.', '缓存失效方面的 bug，正是用户仍然看到旧头像的原因。', ARRAY['database', 'caching']::text[], null, null, 260, true),
  ('dev-message-queue', 'developer', 'message queue', '消息队列', 'n.', 'A system that stores messages so they can be processed asynchronously, often in order.', 'Order events are placed on a message queue so downstream services can process them at their own pace.', '订单事件被放入消息队列，让下游服务可以按自己的节奏处理。', ARRAY['database', 'caching']::text[], null, null, 261, true),
  ('dev-pub-sub', 'developer', 'pub/sub', '发布订阅模式', 'n.', 'A messaging pattern where publishers send messages to a topic and subscribers receive them without direct coupling.', 'We used pub/sub so new services can listen for order events without touching the checkout code.', '我们用发布订阅模式，让新服务可以监听订单事件，而不需要改动结算代码。', ARRAY['database', 'caching']::text[], null, 'pub sub', 262, true),
  ('dev-connection-pool', 'developer', 'connection pool', '连接池', 'n.', 'A cache of reusable database connections that avoids the cost of opening a new one for every request.', 'We tuned the connection pool size after seeing requests queue up under load.', '我们在观察到高负载下请求排队后，调整了连接池的大小。', ARRAY['database', 'caching']::text[], null, null, 263, true),
  ('dev-database-migration', 'developer', 'database migration', '数据库迁移', 'n.', 'A versioned, scripted change to a database schema, applied incrementally over time.', 'The database migration adds a new column with a default value for existing rows.', '这次数据库迁移新增了一列，并为已有数据行设置了默认值。', ARRAY['database', 'caching']::text[], null, null, 264, true),
  ('dev-orm', 'developer', 'ORM', '对象关系映射', 'abbr.', 'A tool that lets developers work with database records as objects instead of writing raw SQL.', 'The ORM generated an inefficient query, so we dropped down to raw SQL for this one case.', '这个 ORM 生成了一条低效的查询，所以我们在这一处改用了原生 SQL。', ARRAY['database', 'caching']::text[], null, 'O R M', 265, true),
  ('dev-read-replica', 'developer', 'read replica', '只读副本', 'n.', 'A copy of a database used to serve read queries and reduce load on the primary database.', 'Reporting queries run against a read replica so they never slow down the main application.', '报表查询都跑在只读副本上，这样就不会拖慢主应用。', ARRAY['database', 'caching']::text[], null, null, 266, true),
  ('dev-data-consistency', 'developer', 'data consistency', '数据一致性', 'n.', 'The guarantee that data remains accurate and valid across all copies and operations.', 'We added a validation step to protect data consistency between the two systems.', '我们加了一步校验，来保护这两个系统之间的数据一致性。', ARRAY['database', 'caching']::text[], null, null, 267, true),
  ('dev-in-memory-database', 'developer', 'in-memory database', '内存数据库', 'n.', 'A database that stores data primarily in RAM instead of on disk for very fast access.', 'We store session data in an in-memory database so lookups take microseconds.', '我们把会话数据存在内存数据库里，这样查找只需要微秒级的时间。', ARRAY['database', 'caching']::text[], null, null, 268, true),
  ('dev-batch-processing', 'developer', 'batch processing', '批处理', 'n.', 'Processing a large group of records together as a single job, rather than one at a time.', 'The nightly batch processing job recalculates every customer''s usage totals.', '每晚的批处理任务会重新计算每个客户的用量总计。', ARRAY['database', 'caching']::text[], null, null, 269, true),
  ('dev-stream-processing', 'developer', 'stream processing', '流处理', 'n.', 'Processing data continuously as it arrives, rather than in large batches.', 'Stream processing lets us update the dashboard within seconds of an event occurring.', '流处理让我们能在事件发生几秒钟内就更新仪表盘。', ARRAY['database', 'caching']::text[], null, null, 270, true),
  ('dev-write-ahead-log', 'developer', 'write-ahead log', '预写日志', 'n.', 'A log that records changes before they are applied to the database, used to recover from crashes.', 'The database replayed the write-ahead log to recover the transactions lost in the crash.', '数据库通过重放预写日志，恢复了因崩溃而丢失的事务。', ARRAY['database', 'caching']::text[], null, null, 271, true),
  ('dev-database-rollback', 'developer', 'database rollback', '数据库回滚', 'n.', 'Undoing changes made during a transaction, restoring the database to its previous state.', 'The migration triggered a database rollback after it failed halfway through.', '这次迁移执行到一半失败后触发了数据库回滚。', ARRAY['database', 'caching']::text[], null, null, 272, true),
  ('dev-full-text-search', 'developer', 'full-text search', '全文检索', 'n.', 'Searching for matching words or phrases across the entire content of documents or records.', 'We added full-text search so users can find articles by keyword instead of exact title.', '我们加上了全文检索功能，让用户可以按关键词而不是精确标题来查找文章。', ARRAY['database', 'caching']::text[], null, null, 273, true),
  ('dev-dom', 'developer', 'DOM', '文档对象模型', 'abbr.', 'A tree-structured representation of a web page that scripts can read and modify.', 'Directly manipulating the DOM in a loop caused the page to feel sluggish.', '在循环里直接操作 DOM 让页面感觉很卡顿。', ARRAY['frontend', 'mobile']::text[], null, 'D O M', 274, true),
  ('dev-ui-component', 'developer', 'UI component', '界面组件', 'n.', 'A reusable, self-contained piece of a user interface, such as a button or card.', 'We extracted the badge into a shared UI component used across five screens.', '我们把这个徽标提取成了一个共享的界面组件，在五个页面中复用。', ARRAY['frontend', 'mobile']::text[], null, 'U I component', 275, true),
  ('dev-state-management', 'developer', 'state management', '状态管理', 'n.', 'The approach used to store, update, and share an application''s data across its UI.', 'As the app grew, we needed a more structured approach to state management.', '随着应用规模增长，我们需要一套更规范的状态管理方案。', ARRAY['frontend', 'mobile']::text[], null, null, 276, true),
  ('dev-props', 'developer', 'props', '属性（组件传入参数）', 'n.', 'The input values passed into a UI component from its parent, used to configure how it renders.', 'Pass the item data down as props instead of fetching it again inside the component.', '把数据作为 props 传下去，而不是在组件内部再重新获取一次。', ARRAY['frontend', 'mobile']::text[], null, null, 277, true),
  ('dev-responsive-design', 'developer', 'responsive design', '响应式设计', 'n.', 'A design approach where a layout adapts smoothly to different screen sizes.', 'The dashboard uses responsive design so it looks right on both phones and tablets.', '这个仪表盘采用了响应式设计，在手机和平板上都能正常显示。', ARRAY['frontend', 'mobile']::text[], null, null, 278, true),
  ('dev-single-page-application', 'developer', 'single-page application', '单页应用', 'n.', 'A web application that loads a single HTML page and updates content dynamically without full page reloads.', 'As a single-page application, navigating between screens never triggers a full page reload.', '作为一个单页应用，在页面之间切换时从来不会触发整页刷新。', ARRAY['frontend', 'mobile']::text[], null, null, 279, true),
  ('dev-virtual-dom', 'developer', 'virtual DOM', '虚拟 DOM', 'n.', 'An in-memory representation of the UI that a framework uses to compute the minimal real DOM updates needed.', 'The framework diffs the virtual DOM before touching the real page at all.', '这个框架会先比较虚拟 DOM 的差异，然后才去改动真正的页面。', ARRAY['frontend', 'mobile']::text[], null, 'virtual D O M', 280, true),
  ('dev-event-listener', 'developer', 'event listener', '事件监听器', 'n.', 'A function registered to run automatically when a specific event, like a click, occurs.', 'Remove the event listener when the component unmounts to avoid a memory leak.', '组件卸载时要移除这个事件监听器，避免内存泄漏。', ARRAY['frontend', 'mobile']::text[], null, null, 281, true),
  ('dev-css-selector', 'developer', 'CSS selector', 'CSS 选择器', 'n.', 'A pattern used to select which HTML elements a style rule applies to.', 'The CSS selector was too broad and accidentally styled elements outside the card.', '这个 CSS 选择器范围太宽，意外地把卡片外部的元素也一起加上了样式。', ARRAY['frontend', 'mobile']::text[], null, 'C S S selector', 282, true),
  ('dev-flexbox', 'developer', 'flexbox', '弹性盒布局', 'n.', 'A CSS layout model that arranges elements along a row or column and distributes space between them.', 'We used flexbox to center the button both vertically and horizontally.', '我们用弹性盒布局把按钮在垂直和水平方向都居中了。', ARRAY['frontend', 'mobile']::text[], null, null, 283, true),
  ('dev-media-query', 'developer', 'media query', '媒体查询', 'n.', 'A CSS rule that applies styles conditionally based on screen size or device characteristics.', 'A media query hides the sidebar once the screen gets narrower than a tablet.', '一条媒体查询规则会在屏幕宽度小于平板尺寸时隐藏侧边栏。', ARRAY['frontend', 'mobile']::text[], null, null, 284, true),
  ('dev-accessibility', 'developer', 'accessibility', '无障碍访问', 'n.', 'Designing software so people with disabilities can use it effectively, such as with screen readers.', 'We added accessibility labels so screen reader users know what each button does.', '我们加上了无障碍标签，让使用屏幕阅读器的用户也能知道每个按钮的作用。', ARRAY['frontend', 'mobile']::text[], null, null, 285, true),
  ('dev-lazy-loading', 'developer', 'lazy loading', '懒加载', 'n.', 'Deferring the loading of content or resources until they are actually needed.', 'Lazy loading the images below the fold made the initial page load noticeably faster.', '对首屏以下的图片做懒加载，让页面初次加载明显变快了。', ARRAY['frontend', 'mobile']::text[], null, null, 286, true),
  ('dev-bundler', 'developer', 'bundler', '打包工具', 'n.', 'A tool that combines and optimizes multiple source files into a smaller set of files for production.', 'Switching bundlers cut our production bundle size by a third.', '更换打包工具让我们的生产环境包体积减小了三分之一。', ARRAY['frontend', 'mobile']::text[], null, null, 287, true),
  ('dev-transpiler', 'developer', 'transpiler', '转译器', 'n.', 'A tool that converts source code written in one language or version into another equivalent form.', 'The transpiler converts our modern syntax into code older browsers can run.', '这个转译器会把我们使用的现代语法转换成旧版浏览器也能运行的代码。', ARRAY['frontend', 'mobile']::text[], null, null, 288, true),
  ('dev-hot-reload', 'developer', 'hot reload', '热重载', 'n.', 'Updating running code in an app instantly as you save changes, without a full restart.', 'Hot reload lets us see UI tweaks in the simulator within a second.', '热重载让我们能在一秒钟内就在模拟器里看到界面调整的效果。', ARRAY['frontend', 'mobile']::text[], null, null, 289, true),
  ('dev-native-module', 'developer', 'native module', '原生模块', 'n.', 'A piece of platform-specific code that exposes native functionality to a cross-platform app.', 'We wrote a small native module to access the device''s biometric sensor.', '我们写了一个小的原生模块，用来访问设备的生物识别传感器。', ARRAY['frontend', 'mobile']::text[], null, null, 290, true),
  ('dev-cross-platform-development', 'developer', 'cross-platform development', '跨平台开发', 'n.', 'Building software that runs on multiple operating systems from a single codebase.', 'Cross-platform development let a small team ship the same app on both iOS and Android.', '跨平台开发让一个小团队就能把同一个应用发布到 iOS 和 Android 两个平台。', ARRAY['frontend', 'mobile']::text[], null, null, 291, true),
  ('dev-gesture-recognizer', 'developer', 'gesture recognizer', '手势识别器', 'n.', 'A component that detects touch patterns like taps, swipes, or pinches and triggers corresponding actions.', 'We attached a gesture recognizer to let users swipe the card away.', '我们加了一个手势识别器，让用户可以滑动划走这张卡片。', ARRAY['frontend', 'mobile']::text[], null, null, 292, true),
  ('dev-viewport', 'developer', 'viewport', '视口', 'n.', 'The visible area of a page or screen where content is rendered.', 'The modal is centered relative to the viewport, not the whole document.', '这个弹窗是相对于视口居中的，而不是相对于整个文档。', ARRAY['frontend', 'mobile']::text[], null, null, 293, true),
  ('dev-layout-constraint', 'developer', 'layout constraint', '布局约束', 'n.', 'A rule that defines the position or size of a UI element relative to others.', 'A conflicting layout constraint was silently overriding the button''s width.', '一个相互冲突的布局约束悄悄覆盖了这个按钮的宽度设置。', ARRAY['frontend', 'mobile']::text[], null, null, 294, true),
  ('dev-main-thread', 'developer', 'main thread', '主线程', 'n.', 'The thread responsible for handling UI updates and user interaction; blocking it freezes the interface.', 'Move the heavy computation off the main thread so the UI doesn''t freeze.', '把这个繁重的计算移出主线程，避免界面卡死。', ARRAY['frontend', 'mobile']::text[], null, null, 295, true),
  ('dev-push-notification', 'developer', 'push notification', '推送通知', 'n.', 'A message sent from a server to a device to alert the user even when the app isn''t open.', 'Users can turn off push notifications for promotional messages in settings.', '用户可以在设置中关闭促销类推送通知。', ARRAY['frontend', 'mobile']::text[], null, null, 296, true),
  ('dev-deep-linking', 'developer', 'deep linking', '深度链接', 'n.', 'Using a URL to navigate directly to a specific screen or piece of content inside an app.', 'Deep linking lets a marketing email open the exact product page in the app.', '深度链接让营销邮件可以直接在应用内打开指定的商品页面。', ARRAY['frontend', 'mobile']::text[], null, null, 297, true),
  ('dev-offline-first', 'developer', 'offline-first', '离线优先', 'adj.', 'An app design approach where core features work without a network connection, syncing later when one is available.', 'We designed the notes feature offline-first so users can keep writing on a plane.', '我们把笔记功能设计成了离线优先，让用户即使在飞机上也能继续书写。', ARRAY['frontend', 'mobile']::text[], null, null, 298, true),
  ('dev-progressive-web-app', 'developer', 'progressive web app', '渐进式网页应用', 'n.', 'A web application that offers app-like features such as offline support and installability.', 'The progressive web app can be installed on the home screen without going through an app store.', '这个渐进式网页应用不需要通过应用商店，就能安装到主屏幕上。', ARRAY['frontend', 'mobile']::text[], null, null, 299, true),
  ('dev-animation-frame', 'developer', 'animation frame', '动画帧', 'n.', 'A single rendered step in an animation sequence, typically synced to the screen''s refresh rate.', 'Dropped animation frames were what made the scrolling feel janky.', '动画帧的丢失正是滚动效果显得卡顿的原因。', ARRAY['frontend', 'mobile']::text[], null, null, 300, true),
  ('dev-touch-event', 'developer', 'touch event', '触摸事件', 'n.', 'An event triggered by a user''s finger touching, moving on, or leaving the screen.', 'We listen for the touch event to start dragging the card.', '我们监听触摸事件来触发这张卡片的拖动。', ARRAY['frontend', 'mobile']::text[], null, null, 301, true),
  ('dev-screen-reader-support', 'developer', 'screen reader support', '屏幕阅读器支持', 'n.', 'Ensuring an app''s content and controls are correctly announced by assistive screen-reading software.', 'We tested screen reader support before releasing the redesigned checkout flow.', '我们在发布重新设计的结算流程之前测试了屏幕阅读器支持情况。', ARRAY['frontend', 'mobile']::text[], null, null, 302, true),
  ('dev-software-architecture', 'developer', 'software architecture', '软件架构', 'n.', 'The high-level structure of a system, including its components and how they interact.', 'The team spent a week evaluating the software architecture before committing to it.', '团队花了一周时间评估这个软件架构，然后才最终确定下来。', ARRAY['architecture', 'design-patterns']::text[], null, null, 303, true),
  ('dev-design-pattern', 'developer', 'design pattern', '设计模式', 'n.', 'A reusable, general solution to a common problem in software design.', 'Recognizing the design pattern made the unfamiliar codebase much easier to follow.', '认出这个设计模式之后，这个陌生的代码库就变得容易理解多了。', ARRAY['architecture', 'design-patterns']::text[], null, null, 304, true),
  ('dev-singleton-pattern', 'developer', 'singleton pattern', '单例模式', 'n.', 'A design pattern that restricts a class to a single, shared instance.', 'The logger is implemented with a singleton pattern so every module writes to the same instance.', '这个日志组件用单例模式实现，所有模块都写入同一个实例。', ARRAY['architecture', 'design-patterns']::text[], null, null, 305, true),
  ('dev-factory-pattern', 'developer', 'factory pattern', '工厂模式', 'n.', 'A design pattern that centralizes object creation logic instead of scattering it throughout the code.', 'A factory pattern hides which concrete class gets created based on the input type.', '工厂模式把根据输入类型决定创建哪个具体类的逻辑隐藏了起来。', ARRAY['architecture', 'design-patterns']::text[], null, null, 306, true),
  ('dev-observer-pattern', 'developer', 'observer pattern', '观察者模式', 'n.', 'A design pattern where one object notifies a list of subscribers whenever its state changes.', 'The UI updates automatically because it subscribes using the observer pattern.', '界面能自动更新，是因为它通过观察者模式订阅了状态变化。', ARRAY['architecture', 'design-patterns']::text[], null, null, 307, true),
  ('dev-dependency-injection', 'developer', 'dependency injection', '依赖注入', 'n.', 'A technique where an object''s dependencies are provided from outside rather than created internally.', 'Dependency injection makes it easy to swap in a fake database for testing.', '依赖注入让我们很容易在测试时替换成一个假的数据库实现。', ARRAY['architecture', 'design-patterns']::text[], null, null, 308, true),
  ('dev-mvc-pattern', 'developer', 'MVC pattern', 'MVC 架构模式', 'n.', 'A pattern that separates an application into model, view, and controller layers.', 'The MVC pattern keeps the business logic in the model, away from the view code.', 'MVC 架构模式把业务逻辑保留在模型层，和视图代码分离开来。', ARRAY['architecture', 'design-patterns']::text[], null, 'M V C pattern', 309, true),
  ('dev-mvvm-pattern', 'developer', 'MVVM pattern', 'MVVM 架构模式', 'n.', 'A pattern that separates an application into model, view, and view model layers, with the view model exposing state to the view.', 'We moved to an MVVM pattern so the view stays a thin layer over the view model''s state.', '我们改用了 MVVM 架构模式，让视图只是视图模型状态之上的一层薄壳。', ARRAY['architecture', 'design-patterns']::text[], null, 'M V V M pattern', 310, true),
  ('dev-layered-architecture', 'developer', 'layered architecture', '分层架构', 'n.', 'An architecture that organizes a system into layers, each depending only on the layer below it.', 'The layered architecture keeps the database code from leaking into the presentation layer.', '这种分层架构避免了数据库相关代码渗透进展示层。', ARRAY['architecture', 'design-patterns']::text[], null, null, 311, true),
  ('dev-domain-driven-design', 'developer', 'domain-driven design', '领域驱动设计', 'n.', 'An approach to software design that models code closely around the business domain and its language.', 'Domain-driven design helped us align the code''s terminology with how the business actually talks.', '领域驱动设计帮助我们让代码中的术语和业务实际使用的说法保持一致。', ARRAY['architecture', 'design-patterns']::text[], null, null, 312, true),
  ('dev-separation-of-concerns', 'developer', 'separation of concerns', '关注点分离', 'phr.', 'A design principle that keeps distinct responsibilities isolated in different parts of the code.', 'Poor separation of concerns meant a single file handled validation, storage, and formatting all at once.', '关注点分离没有做好，导致一个文件同时处理校验、存储和格式化。', ARRAY['architecture', 'design-patterns']::text[], null, null, 313, true),
  ('dev-loose-coupling', 'developer', 'loose coupling', '松耦合', 'n.', 'A design quality where components depend on each other as little as possible.', 'Loose coupling let us replace the email provider without touching the rest of the system.', '松耦合让我们能够替换邮件服务商，而不用改动系统的其他部分。', ARRAY['architecture', 'design-patterns']::text[], null, null, 314, true),
  ('dev-tight-coupling', 'developer', 'tight coupling', '紧耦合', 'n.', 'A design quality where components depend heavily on each other''s internal details.', 'Tight coupling between these two modules means a change in one always breaks the other.', '这两个模块之间的紧耦合意味着改动其中一个总会破坏另一个。', ARRAY['architecture', 'design-patterns']::text[], null, null, 315, true),
  ('dev-cohesion', 'developer', 'cohesion', '内聚性', 'n.', 'The degree to which the responsibilities within a single module are closely related.', 'Splitting the utility file improved cohesion — each new file now does one clear thing.', '拆分这个工具文件提升了内聚性——现在每个新文件只做一件明确的事。', ARRAY['architecture', 'design-patterns']::text[], null, null, 316, true),
  ('dev-solid-principles', 'developer', 'SOLID principles', 'SOLID 设计原则', 'n.', 'A set of five object-oriented design principles intended to make software easier to maintain and extend.', 'The interviewer asked me to walk through how the SOLID principles apply to this class.', '面试官让我讲一下 SOLID 设计原则是如何应用到这个类上的。', ARRAY['architecture', 'design-patterns']::text[], null, null, 317, true),
  ('dev-single-responsibility-principle', 'developer', 'single responsibility principle', '单一职责原则', 'n.', 'The design principle that a class or module should have only one reason to change.', 'This class violates the single responsibility principle by handling both parsing and rendering.', '这个类既处理解析又处理渲染，违反了单一职责原则。', ARRAY['architecture', 'design-patterns']::text[], null, null, 318, true),
  ('dev-open-closed-principle', 'developer', 'open/closed principle', '开闭原则', 'n.', 'The design principle that code should be open for extension but closed for modification.', 'Following the open/closed principle, we added a new payment method without editing the existing ones.', '按照开闭原则，我们新增了一种支付方式，而没有修改已有的那些。', ARRAY['architecture', 'design-patterns']::text[], null, null, 319, true),
  ('dev-interface-segregation-principle', 'developer', 'interface segregation principle', '接口隔离原则', 'n.', 'The design principle that clients should not be forced to depend on methods they don''t use.', 'We split the huge interface into smaller ones to follow the interface segregation principle.', '为了遵循接口隔离原则，我们把这个庞大的接口拆分成了几个更小的接口。', ARRAY['architecture', 'design-patterns']::text[], null, null, 320, true),
  ('dev-inversion-of-control', 'developer', 'inversion of control', '控制反转', 'n.', 'A design principle where the flow of control is handed over to a framework or container instead of the code itself.', 'Inversion of control means the framework calls our code, not the other way around.', '控制反转意味着是框架来调用我们的代码，而不是反过来。', ARRAY['architecture', 'design-patterns']::text[], null, null, 321, true),
  ('dev-adapter-pattern', 'developer', 'adapter pattern', '适配器模式', 'n.', 'A design pattern that converts one interface into another that the rest of the code expects.', 'We wrote an adapter pattern so the legacy API fits the interface our new code expects.', '我们写了一个适配器模式，让这个老旧的接口能符合新代码所期望的接口形式。', ARRAY['architecture', 'design-patterns']::text[], null, null, 322, true),
  ('dev-strategy-pattern', 'developer', 'strategy pattern', '策略模式', 'n.', 'A design pattern that lets an algorithm be selected and swapped at runtime through a shared interface.', 'The strategy pattern lets us switch pricing rules without touching the checkout logic.', '策略模式让我们可以切换定价规则，而不用改动结算逻辑。', ARRAY['architecture', 'design-patterns']::text[], null, null, 323, true),
  ('dev-decorator-pattern', 'developer', 'decorator pattern', '装饰器模式', 'n.', 'A design pattern that adds new behavior to an object dynamically by wrapping it.', 'We used the decorator pattern to add caching around the existing data fetcher.', '我们用装饰器模式给已有的数据获取逻辑包裹上了一层缓存。', ARRAY['architecture', 'design-patterns']::text[], null, null, 324, true),
  ('dev-facade-pattern', 'developer', 'facade pattern', '外观模式', 'n.', 'A design pattern that provides a simplified interface to a more complex subsystem.', 'The facade pattern hides three different SDKs behind one simple analytics interface.', '外观模式把三个不同的 SDK 隐藏在了一个简单的统计接口后面。', ARRAY['architecture', 'design-patterns']::text[], null, null, 325, true),
  ('dev-builder-pattern', 'developer', 'builder pattern', '建造者模式', 'n.', 'A design pattern that constructs a complex object step by step through a fluent interface.', 'We used a builder pattern to construct the request instead of a constructor with ten parameters.', '我们用建造者模式来构造这个请求对象，而不是用一个带十个参数的构造函数。', ARRAY['architecture', 'design-patterns']::text[], null, null, 326, true),
  ('dev-anti-pattern', 'developer', 'anti-pattern', '反模式', 'n.', 'A common but ineffective or counterproductive approach to solving a recurring problem.', 'Catching every exception and doing nothing with it is a classic anti-pattern.', '捕获所有异常却不做任何处理，是一个典型的反模式。', ARRAY['architecture', 'design-patterns']::text[], null, null, 327, true),
  ('dev-technical-specification', 'developer', 'technical specification', '技术方案文档', 'n.', 'A written document that describes the design, constraints, and implementation approach for a feature or system.', 'Write a technical specification before starting on such a large piece of work.', '在开始做这么大的工作之前，先写一份技术方案文档。', ARRAY['architecture', 'design-patterns']::text[], null, null, 328, true),
  ('dev-proof-of-concept', 'developer', 'proof of concept', '概念验证', 'n.', 'A small, quick implementation built to test whether an idea is technically feasible.', 'We built a proof of concept over two days to see if the approach was even viable.', '我们花了两天时间做了一个概念验证，来看看这个方案是否可行。', ARRAY['architecture', 'design-patterns']::text[], null, null, 329, true),
  ('dev-system-design', 'developer', 'system design', '系统设计', 'n.', 'The process of defining the architecture, components, and interfaces of a large software system.', 'The system design needs to account for ten times today''s traffic.', '这次系统设计需要考虑到当前流量十倍的规模。', ARRAY['architecture', 'design-patterns']::text[], null, null, 330, true),
  ('dev-event-sourcing', 'developer', 'event sourcing', '事件溯源', 'n.', 'A pattern where state changes are stored as a sequence of events instead of just the current state.', 'With event sourcing, we can always replay the events to see how an order reached its current state.', '有了事件溯源，我们随时可以重放事件，看看一个订单是如何变成当前状态的。', ARRAY['architecture', 'design-patterns']::text[], null, null, 331, true),
  ('dev-concurrency', 'developer', 'concurrency', '并发', 'n.', 'The ability of a system to handle multiple tasks making progress during overlapping time periods.', 'Handling concurrency correctly is what made this feature so much harder than it looked.', '正确处理并发问题，正是这个功能比看上去难得多的原因。', ARRAY['performance', 'concurrency']::text[], null, null, 332, true),
  ('dev-parallelism', 'developer', 'parallelism', '并行', 'n.', 'Executing multiple tasks at literally the same time, typically on multiple processor cores.', 'We used parallelism to process each image on a separate core simultaneously.', '我们用并行的方式，让每张图片同时在不同的核心上处理。', ARRAY['performance', 'concurrency']::text[], null, null, 333, true),
  ('dev-thread', 'developer', 'thread', '线程', 'n.', 'The smallest unit of execution that can be scheduled by an operating system.', 'Never update the UI from a background thread directly.', '永远不要直接从后台线程更新界面。', ARRAY['performance', 'concurrency']::text[], null, null, 334, true),
  ('dev-multithreading', 'developer', 'multithreading', '多线程', 'n.', 'Running multiple threads within a single program to perform tasks concurrently.', 'Multithreading introduced subtle bugs that only showed up under heavy load.', '多线程引入了一些只有在高负载下才会出现的隐蔽 bug。', ARRAY['performance', 'concurrency']::text[], null, null, 335, true),
  ('dev-thread-pool', 'developer', 'thread pool', '线程池', 'n.', 'A group of pre-created, reusable threads that execute tasks from a shared queue.', 'We resized the thread pool after profiling showed too many threads were sitting idle.', '在性能分析发现大量线程处于空闲状态后，我们调整了线程池的大小。', ARRAY['performance', 'concurrency']::text[], null, null, 336, true),
  ('dev-mutex', 'developer', 'mutex', '互斥锁', 'n.', 'A lock that ensures only one thread can access a shared resource at a time.', 'We wrapped the shared counter update in a mutex to prevent a race condition.', '我们用互斥锁把这个共享计数器的更新操作包裹起来，以防止竞态条件。', ARRAY['performance', 'concurrency']::text[], null, null, 337, true),
  ('dev-semaphore', 'developer', 'semaphore', '信号量', 'n.', 'A synchronization tool that limits how many threads can access a resource at the same time.', 'A semaphore limits the number of concurrent downloads to four.', '一个信号量把并发下载的数量限制在了四个。', ARRAY['performance', 'concurrency']::text[], null, null, 338, true),
  ('dev-atomic-operation', 'developer', 'atomic operation', '原子操作', 'n.', 'An operation that completes fully or not at all, with no other thread able to observe it half-done.', 'Incrementing the counter needs to be an atomic operation, or two threads can lose an update.', '递增这个计数器必须是原子操作，否则两个线程可能会互相覆盖对方的更新。', ARRAY['performance', 'concurrency']::text[], null, null, 339, true),
  ('dev-memory-management', 'developer', 'memory management', '内存管理', 'n.', 'The process of allocating and releasing memory a program uses while it runs.', 'Manual memory management gives more control but also more room for bugs.', '手动内存管理带来了更多控制权，但也带来了更多出错的空间。', ARRAY['performance', 'concurrency']::text[], null, null, 340, true),
  ('dev-resource-leak', 'developer', 'resource leak', '资源泄漏', 'n.', 'A bug where a program fails to release a resource, such as a file handle or connection, after it''s no longer needed.', 'An unclosed file handle was causing a slow resource leak.', '一个没有关闭的文件句柄正在导致缓慢的资源泄漏。', ARRAY['performance', 'concurrency']::text[], null, null, 341, true),
  ('dev-throughput', 'developer', 'throughput', '吞吐量', 'n.', 'The amount of work a system can process in a given period of time.', 'The new batching approach doubled the pipeline''s throughput.', '新的批处理方式让这个流水线的吞吐量翻了一倍。', ARRAY['performance', 'concurrency']::text[], null, null, 342, true),
  ('dev-bottleneck', 'developer', 'bottleneck', '性能瓶颈', 'n.', 'The single component that limits the overall performance of a system.', 'Profiling showed the database query was the real bottleneck, not the rendering code.', '性能分析显示真正的瓶颈是这条数据库查询，而不是渲染代码。', ARRAY['performance', 'concurrency']::text[], null, null, 343, true),
  ('dev-profiling', 'developer', 'profiling', '性能分析', 'n.', 'Measuring where a program spends its time and resources to find optimization opportunities.', 'Profiling revealed that most of the time was spent parsing the same file repeatedly.', '性能分析显示大部分时间都花在了反复解析同一个文件上。', ARRAY['performance', 'concurrency']::text[], null, null, 344, true),
  ('dev-lazy-evaluation', 'developer', 'lazy evaluation', '惰性求值', 'n.', 'Delaying the computation of a value until it is actually needed.', 'Lazy evaluation means this expensive calculation only runs if the result is actually used.', '惰性求值意味着这个昂贵的计算只有在结果真正被用到时才会执行。', ARRAY['performance', 'concurrency']::text[], null, null, 345, true),
  ('dev-eager-evaluation', 'developer', 'eager evaluation', '及早求值', 'n.', 'Computing a value as soon as it''s defined, rather than waiting until it''s needed.', 'We switched to eager evaluation here so errors surface immediately instead of later.', '我们在这里改用了及早求值，让错误能立刻暴露出来，而不是延后才出现。', ARRAY['performance', 'concurrency']::text[], null, null, 346, true),
  ('dev-caching-strategy', 'developer', 'caching strategy', '缓存策略', 'n.', 'The rules that determine what to cache, how long to keep it, and when to refresh it.', 'We changed the caching strategy from time-based expiry to event-based invalidation.', '我们把缓存策略从基于时间过期改成了基于事件失效。', ARRAY['performance', 'concurrency']::text[], null, null, 347, true),
  ('dev-memoization', 'developer', 'memoization', '记忆化', 'n.', 'Caching the results of expensive function calls so repeated calls with the same input return instantly.', 'Memoization avoided recalculating the same expensive result on every re-render.', '记忆化避免了每次重新渲染都要重新计算同一个昂贵的结果。', ARRAY['performance', 'concurrency']::text[], null, null, 348, true),
  ('dev-context-switching', 'developer', 'context switching', '上下文切换', 'n.', 'The process of storing and restoring the state of a thread so a CPU can switch between tasks.', 'Too many threads caused excessive context switching, hurting overall performance.', '线程数量过多导致了过度的上下文切换，反而影响了整体性能。', ARRAY['performance', 'concurrency']::text[], null, null, 349, true),
  ('dev-cpu-bound', 'developer', 'CPU-bound', 'CPU 密集型', 'adj.', 'Describing a task whose speed is limited primarily by processor computation rather than I/O.', 'This task is CPU-bound, so adding more network capacity won''t speed it up.', '这个任务是 CPU 密集型的，增加网络带宽并不会让它变快。', ARRAY['performance', 'concurrency']::text[], null, 'C P U bound', 350, true),
  ('dev-io-bound', 'developer', 'I/O-bound', 'I/O 密集型', 'adj.', 'Describing a task whose speed is limited primarily by input/output operations, such as disk or network access.', 'Since the job is I/O-bound, running it on more CPU cores barely helps.', '因为这个任务是 I/O 密集型的，增加 CPU 核心数几乎没什么帮助。', ARRAY['performance', 'concurrency']::text[], null, 'I O bound', 351, true),
  ('dev-non-blocking-io', 'developer', 'non-blocking I/O', '非阻塞 I/O', 'n.', 'An I/O model where operations return immediately instead of waiting, letting the program handle other work.', 'Non-blocking I/O lets a single server handle thousands of open connections at once.', '非阻塞 I/O 让单台服务器能够同时处理成千上万个打开的连接。', ARRAY['performance', 'concurrency']::text[], null, 'non-blocking I O', 352, true),
  ('dev-event-loop', 'developer', 'event loop', '事件循环', 'n.', 'A runtime mechanism that continuously checks for and dispatches pending events or callbacks.', 'Blocking the event loop with a synchronous call froze the entire server.', '用一次同步调用阻塞了事件循环，导致整个服务器都卡住了。', ARRAY['performance', 'concurrency']::text[], null, null, 353, true),
  ('dev-thread-safety', 'developer', 'thread safety', '线程安全', 'n.', 'A property of code that behaves correctly when accessed by multiple threads at the same time.', 'We added thread safety to this cache after seeing corrupted entries under load.', '在观察到高负载下缓存条目出现损坏后，我们为这个缓存加上了线程安全保证。', ARRAY['performance', 'concurrency']::text[], null, null, 354, true),
  ('dev-resource-contention', 'developer', 'resource contention', '资源争用', 'n.', 'A situation where multiple processes or threads compete for the same limited resource.', 'Resource contention on the database connection pool was slowing every request down.', '数据库连接池的资源争用拖慢了每一个请求。', ARRAY['performance', 'concurrency']::text[], null, null, 355, true),
  ('dev-performance-tuning', 'developer', 'performance tuning', '性能调优', 'n.', 'The process of adjusting a system to improve its speed, throughput, or resource usage.', 'After a round of performance tuning, page load time dropped by half.', '经过一轮性能调优，页面加载时间减少了一半。', ARRAY['performance', 'concurrency']::text[], null, null, 356, true),
  ('dev-cold-start', 'developer', 'cold start', '冷启动', 'n.', 'The extra delay when a system or function starts running from an idle or freshly initialized state.', 'The serverless function''s cold start added almost a second to the first request.', '这个无服务器函数的冷启动给第一次请求增加了近一秒的延迟。', ARRAY['performance', 'concurrency']::text[], null, null, 357, true),
  ('dev-spin-lock', 'developer', 'spin lock', '自旋锁', 'n.', 'A lock where a thread repeatedly checks in a loop until the lock becomes available, rather than sleeping.', 'A spin lock made sense here since the critical section only takes a few instructions.', '因为这段临界区代码只需要几条指令，所以用自旋锁在这里是合理的。', ARRAY['performance', 'concurrency']::text[], null, null, 358, true),
  ('dev-worker-thread', 'developer', 'worker thread', '工作线程', 'n.', 'A background thread dedicated to running tasks off the main thread.', 'We offloaded image processing to a worker thread to keep the UI responsive.', '我们把图片处理任务转移到了一个工作线程上，以保持界面响应流畅。', ARRAY['performance', 'concurrency']::text[], null, null, 359, true),
  ('dev-authentication-token', 'developer', 'authentication token', '身份验证令牌', 'n.', 'A piece of data issued after login that proves a user''s identity on subsequent requests.', 'The mobile app stores the authentication token securely in the device keychain.', '这个移动端应用把身份验证令牌安全地存储在设备的钥匙串里。', ARRAY['security', 'privacy']::text[], null, null, 360, true),
  ('dev-access-control', 'developer', 'access control', '访问控制', 'n.', 'The set of rules that determine who can access which resources in a system.', 'A gap in access control let regular users reach an admin-only endpoint.', '访问控制上的一个漏洞让普通用户也能访问到仅限管理员的接口。', ARRAY['security', 'privacy']::text[], null, null, 361, true),
  ('dev-role-based-access-control', 'developer', 'role-based access control', '基于角色的访问控制', 'n.', 'An access control model that grants permissions based on a user''s assigned role rather than individually.', 'We introduced role-based access control so permissions are managed by role, not by individual user.', '我们引入了基于角色的访问控制，让权限按角色而不是按单个用户来管理。', ARRAY['security', 'privacy']::text[], null, null, 362, true),
  ('dev-encryption', 'developer', 'encryption', '加密', 'n.', 'The process of converting data into a coded form to prevent unauthorized access.', 'All data is encrypted in transit using encryption between the app and the server.', '应用和服务器之间的所有数据在传输过程中都会加密。', ARRAY['security', 'privacy']::text[], null, null, 363, true),
  ('dev-decryption', 'developer', 'decryption', '解密', 'n.', 'The process of converting encrypted data back into its original, readable form.', 'Decryption of the file failed because the key had already been rotated.', '这个文件的解密失败了，因为密钥已经被轮换过了。', ARRAY['security', 'privacy']::text[], null, null, 364, true),
  ('dev-hashing', 'developer', 'hashing', '哈希（散列）处理', 'n.', 'Converting data into a fixed-size value using a one-way function, commonly used to store passwords securely.', 'Passwords are never stored as plain text — only their hashing result is saved.', '密码从不以明文存储——数据库里只保存它们哈希处理后的结果。', ARRAY['security', 'privacy']::text[], null, null, 365, true),
  ('dev-sql-injection', 'developer', 'SQL injection', 'SQL 注入', 'n.', 'An attack that inserts malicious SQL code through user input to manipulate a database.', 'Using parameterized queries prevents SQL injection even with untrusted user input.', '使用参数化查询可以防止 SQL 注入，即便面对不可信的用户输入也是如此。', ARRAY['security', 'privacy']::text[], null, 'S Q L injection', 366, true),
  ('dev-cross-site-scripting', 'developer', 'cross-site scripting', '跨站脚本攻击', 'n.', 'An attack that injects malicious scripts into pages viewed by other users.', 'We escape all user-generated content to prevent cross-site scripting.', '我们对所有用户生成的内容都进行转义，以防止跨站脚本攻击。', ARRAY['security', 'privacy']::text[], null, null, 367, true),
  ('dev-cross-site-request-forgery', 'developer', 'cross-site request forgery', '跨站请求伪造', 'n.', 'An attack that tricks a logged-in user''s browser into submitting an unwanted request to another site.', 'The form now includes a token to protect against cross-site request forgery.', '这个表单现在带上了一个令牌，用来防范跨站请求伪造。', ARRAY['security', 'privacy']::text[], null, null, 368, true),
  ('dev-vulnerability', 'developer', 'vulnerability', '安全漏洞', 'n.', 'A weakness in a system that could be exploited to cause harm or unauthorized access.', 'The security scan found a vulnerability in an outdated third-party library.', '安全扫描在一个过时的第三方库里发现了一个安全漏洞。', ARRAY['security', 'privacy']::text[], null, null, 369, true),
  ('dev-penetration-testing', 'developer', 'penetration testing', '渗透测试', 'n.', 'Authorized simulated attacks on a system used to find and fix security weaknesses.', 'We hired an outside firm to run penetration testing before the public launch.', '我们在正式公开发布之前，请了一家外部机构进行渗透测试。', ARRAY['security', 'privacy']::text[], null, null, 370, true),
  ('dev-two-factor-authentication', 'developer', 'two-factor authentication', '双因素认证', 'n.', 'A login method that requires two separate forms of verification, such as a password and a code.', 'We strongly recommend enabling two-factor authentication on your account.', '我们强烈建议你为账号开启双因素认证。', ARRAY['security', 'privacy']::text[], null, null, 371, true),
  ('dev-session-hijacking', 'developer', 'session hijacking', '会话劫持', 'n.', 'An attack where someone steals a valid session token to impersonate a logged-in user.', 'Rotating session tokens regularly makes session hijacking much harder to pull off.', '定期轮换会话令牌让会话劫持变得难得多。', ARRAY['security', 'privacy']::text[], null, null, 372, true),
  ('dev-data-breach', 'developer', 'data breach', '数据泄露', 'n.', 'An incident where sensitive data is accessed or exposed without authorization.', 'The company had to notify all affected users after the data breach.', '这次数据泄露发生后，公司不得不通知所有受影响的用户。', ARRAY['security', 'privacy']::text[], null, null, 373, true),
  ('dev-secure-by-design', 'developer', 'secure by design', '安全设计原则', 'phr.', 'Building security into a system''s architecture from the start, rather than adding it later.', 'We treated this API as secure by design, requiring authorization checks at every layer.', '我们按照安全设计原则来构建这个 API，要求在每一层都进行权限检查。', ARRAY['security', 'privacy']::text[], null, null, 374, true),
  ('dev-least-privilege', 'developer', 'least privilege', '最小权限原则', 'n.', 'The principle of giving a user or system only the minimum access needed to do its job.', 'Following least privilege, the service account can only read from this one table.', '按照最小权限原则，这个服务账号只能读取这一张表。', ARRAY['security', 'privacy']::text[], null, null, 375, true),
  ('dev-sensitive-data', 'developer', 'sensitive data', '敏感数据', 'n.', 'Data that requires special protection, such as personal, financial, or health information.', 'Sensitive data like CVs and interview notes should never be logged in plain text.', '像简历和面试笔记这样的敏感数据绝不能以明文形式被记录到日志里。', ARRAY['security', 'privacy']::text[], null, null, 376, true),
  ('dev-data-masking', 'developer', 'data masking', '数据脱敏', 'n.', 'Hiding or obscuring parts of sensitive data so it can be used safely without exposing the real values.', 'Data masking replaces most digits of the card number with asterisks before display.', '数据脱敏会在显示之前把卡号的大部分数字替换成星号。', ARRAY['security', 'privacy']::text[], null, null, 377, true),
  ('dev-audit-log', 'developer', 'audit log', '审计日志', 'n.', 'A record of who did what and when, used to track and review sensitive actions.', 'We checked the audit log to see who had changed the user''s permissions.', '我们查了审计日志，看看是谁修改了这个用户的权限。', ARRAY['security', 'privacy']::text[], null, null, 378, true),
  ('dev-security-patch', 'developer', 'security patch', '安全补丁', 'n.', 'An update released to fix a known security vulnerability.', 'We applied the security patch the same day it was released.', '这个安全补丁发布的当天我们就应用上了。', ARRAY['security', 'privacy']::text[], null, null, 379, true),
  ('dev-firewall', 'developer', 'firewall', '防火墙', 'n.', 'A network security system that controls incoming and outgoing traffic based on defined rules.', 'The firewall blocks all inbound traffic except on the ports we explicitly allow.', '这个防火墙会拦截除我们明确允许的端口之外的所有入站流量。', ARRAY['security', 'privacy']::text[], null, null, 380, true),
  ('dev-ssl-tls', 'developer', 'SSL/TLS', 'SSL/TLS 加密协议', 'n.', 'Protocols that encrypt data sent between a client and a server over a network.', 'The certificate expired, so connections over SSL/TLS started failing.', '证书过期了，导致通过 SSL/TLS 建立的连接开始失败。', ARRAY['security', 'privacy']::text[], null, 'S S L T L S', 381, true),
  ('dev-token-expiration', 'developer', 'token expiration', '令牌过期', 'n.', 'The point after which a security token is no longer considered valid and must be renewed.', 'We shortened token expiration to limit the damage if a token is ever leaked.', '我们缩短了令牌过期时间，以限制万一令牌泄露所造成的损害。', ARRAY['security', 'privacy']::text[], null, null, 382, true),
  ('dev-input-validation', 'developer', 'input validation', '输入校验', 'n.', 'Checking that incoming data meets expected rules before it is processed further.', 'Missing input validation let an empty string through and crashed the report generator.', '缺少输入校验让一个空字符串混了进去，导致报表生成器崩溃。', ARRAY['security', 'privacy']::text[], null, null, 383, true),
  ('dev-sanitize-input', 'developer', 'sanitize input', '清理（净化）输入', 'phr.', 'To remove or escape potentially dangerous characters from user input before using it.', 'Always sanitize input before rendering it back onto the page.', '在把用户输入渲染回页面之前，一定要先清理输入。', ARRAY['security', 'privacy']::text[], null, null, 384, true),
  ('dev-zero-day-vulnerability', 'developer', 'zero-day vulnerability', '零日漏洞', 'n.', 'A security flaw that is exploited before the vendor has released a fix for it.', 'The team worked through the weekend to patch the zero-day vulnerability.', '团队整个周末都在加班修复这个零日漏洞。', ARRAY['security', 'privacy']::text[], null, null, 385, true),
  ('dev-data-anonymization', 'developer', 'data anonymization', '数据匿名化', 'n.', 'Removing or transforming personally identifiable information so individuals can no longer be identified.', 'We apply data anonymization before sharing usage statistics with the analytics team.', '在把使用数据分享给数据分析团队之前，我们会先做数据匿名化处理。', ARRAY['security', 'privacy']::text[], null, null, 386, true),
  ('dev-threat-model', 'developer', 'threat model', '威胁模型', 'n.', 'A structured analysis of potential attackers, attack paths, and risks to a system.', 'Our threat model assumes an attacker could gain access to the internal network.', '我们的威胁模型假设攻击者有可能获得内部网络的访问权限。', ARRAY['security', 'privacy']::text[], null, null, 387, true),
  ('dev-continuous-integration', 'developer', 'continuous integration', '持续集成', 'n.', 'A practice of frequently merging code changes into a shared branch and automatically building and testing them.', 'Continuous integration catches most build failures within minutes of a push.', '持续集成能在代码推送后几分钟内就发现大部分构建失败的问题。', ARRAY['devops', 'cloud']::text[], null, null, 388, true),
  ('dev-continuous-deployment', 'developer', 'continuous deployment', '持续部署', 'n.', 'Automatically releasing every change that passes the pipeline straight to production.', 'With continuous deployment, a merged pull request can be live in production within minutes.', '有了持续部署，一个合并的拉取请求几分钟内就能在生产环境上线。', ARRAY['devops', 'cloud']::text[], null, null, 389, true),
  ('dev-build-pipeline', 'developer', 'build pipeline', '构建流水线', 'n.', 'An automated sequence of steps that compiles, tests, and packages code.', 'The build pipeline failed at the linting stage before it even reached the tests.', '构建流水线在还没跑到测试阶段之前，就在代码检查环节失败了。', ARRAY['devops', 'cloud']::text[], null, null, 390, true),
  ('dev-container', 'developer', 'container', '容器', 'n.', 'A lightweight, isolated package that bundles an application with everything it needs to run.', 'Each service runs in its own container so dependencies never conflict.', '每个服务都运行在自己的容器里，依赖之间不会产生冲突。', ARRAY['devops', 'cloud']::text[], null, null, 391, true),
  ('dev-docker-image', 'developer', 'Docker image', 'Docker 镜像', 'n.', 'A read-only template that contains everything needed to run a container.', 'We rebuild the Docker image automatically whenever the base dependencies change.', '每当基础依赖发生变化时，我们都会自动重新构建 Docker 镜像。', ARRAY['devops', 'cloud']::text[], null, null, 392, true),
  ('dev-kubernetes', 'developer', 'Kubernetes', 'Kubernetes 容器编排系统', 'n.', 'An open-source platform that automates the deployment, scaling, and management of containerized applications.', 'Kubernetes automatically restarts the pod when the health check fails.', '当健康检查失败时，Kubernetes 会自动重启这个 pod。', ARRAY['devops', 'cloud']::text[], null, null, 393, true),
  ('dev-infrastructure-as-code', 'developer', 'infrastructure as code', '基础设施即代码', 'n.', 'Managing and provisioning infrastructure through machine-readable configuration files instead of manual setup.', 'Infrastructure as code lets us recreate the entire environment from a single config file.', '基础设施即代码让我们可以只用一个配置文件就重建整个环境。', ARRAY['devops', 'cloud']::text[], null, null, 394, true),
  ('dev-cloud-provider', 'developer', 'cloud provider', '云服务提供商', 'n.', 'A company that offers computing infrastructure and services over the internet.', 'We chose this cloud provider mainly because of its regional data centers.', '我们选择这家云服务提供商主要是因为它在该地区有数据中心。', ARRAY['devops', 'cloud']::text[], null, null, 395, true),
  ('dev-virtual-machine', 'developer', 'virtual machine', '虚拟机', 'n.', 'A software-based emulation of a physical computer that runs its own operating system.', 'We spun up a virtual machine to test the deployment script in isolation.', '我们启动了一台虚拟机，用来单独测试这个部署脚本。', ARRAY['devops', 'cloud']::text[], null, null, 396, true),
  ('dev-auto-scaling', 'developer', 'auto-scaling', '自动扩缩容', 'n.', 'Automatically adjusting the number of running instances based on current demand.', 'Auto-scaling added three more instances during the traffic spike and removed them afterward.', '自动扩缩容在流量高峰期增加了三个实例，高峰过后又把它们撤下了。', ARRAY['devops', 'cloud']::text[], null, null, 397, true),
  ('dev-deployment-pipeline', 'developer', 'deployment pipeline', '部署流水线', 'n.', 'An automated sequence of stages that moves a build from testing through to production.', 'The deployment pipeline requires a manual approval step before hitting production.', '这条部署流水线在到达生产环境之前需要人工审批这一步。', ARRAY['devops', 'cloud']::text[], null, null, 398, true),
  ('dev-blue-green-deployment', 'developer', 'blue-green deployment', '蓝绿部署', 'n.', 'A release strategy that keeps two identical environments and switches traffic between them to enable instant rollback.', 'Blue-green deployment let us switch back to the previous version instantly when the new one misbehaved.', '蓝绿部署让我们在新版本出问题时能立刻切回上一个版本。', ARRAY['devops', 'cloud']::text[], null, null, 399, true),
  ('dev-canary-release', 'developer', 'canary release', '金丝雀发布', 'n.', 'Rolling out a change to a small subset of users first to catch problems before a full release.', 'The canary release was rolled back after error rates spiked for that small group of users.', '在那一小部分用户的错误率飙升后，这次金丝雀发布被回滚了。', ARRAY['devops', 'cloud']::text[], null, null, 400, true),
  ('dev-deployment-rollback', 'developer', 'deployment rollback', '部署回滚', 'n.', 'Reverting a deployed release back to a previous, known-good version.', 'We triggered a deployment rollback the moment error rates crossed the threshold.', '一旦错误率超过阈值，我们就立刻触发了部署回滚。', ARRAY['devops', 'cloud']::text[], null, null, 401, true),
  ('dev-environment-variable', 'developer', 'environment variable', '环境变量', 'n.', 'A named value set outside the application code, used to configure its behavior per environment.', 'The database URL is read from an environment variable, never hardcoded.', '数据库地址是从环境变量里读取的，从不硬编码。', ARRAY['devops', 'cloud']::text[], null, null, 402, true),
  ('dev-configuration-management', 'developer', 'configuration management', '配置管理', 'n.', 'The practice of systematically tracking and controlling changes to a system''s configuration.', 'Configuration management keeps every server''s settings consistent across the fleet.', '配置管理让整个服务器集群的设置保持一致。', ARRAY['devops', 'cloud']::text[], null, null, 403, true),
  ('dev-artifact-repository', 'developer', 'artifact repository', '制品仓库', 'n.', 'A storage system used to keep and version build outputs, such as packages or images.', 'Every build is uploaded to the artifact repository before it can be deployed.', '每次构建产物都要先上传到制品仓库，然后才能被部署。', ARRAY['devops', 'cloud']::text[], null, null, 404, true),
  ('dev-build-automation', 'developer', 'build automation', '构建自动化', 'n.', 'Automating the steps needed to compile, test, and package software.', 'Build automation removed the last manual step from our release process.', '构建自动化去掉了我们发布流程中最后一个手动步骤。', ARRAY['devops', 'cloud']::text[], null, null, 405, true),
  ('dev-serverless-computing', 'developer', 'serverless computing', '无服务器计算', 'n.', 'A cloud execution model where the provider manages the servers and automatically scales code on demand.', 'We moved the image resizing job to serverless computing so we stop paying for idle servers.', '我们把图片压缩任务迁移到了无服务器计算上，这样就不用再为闲置服务器付费了。', ARRAY['devops', 'cloud']::text[], null, null, 406, true),
  ('dev-provisioning', 'developer', 'provisioning', '资源配置（预配）', 'n.', 'The process of setting up the infrastructure and resources a system needs before it can run.', 'Provisioning a new environment used to take a day; now it takes minutes.', '以前配置一个新环境需要一天时间，现在只需要几分钟。', ARRAY['devops', 'cloud']::text[], null, null, 407, true),
  ('dev-staging-deployment', 'developer', 'staging deployment', '预发布部署', 'n.', 'Deploying a build to a staging environment for final verification before production.', 'Every pull request triggers a staging deployment so reviewers can click through the change.', '每个拉取请求都会触发一次预发布部署，方便审查者亲自点击体验这次改动。', ARRAY['devops', 'cloud']::text[], null, null, 408, true),
  ('dev-deployment-frequency', 'developer', 'deployment frequency', '部署频率', 'n.', 'How often a team ships changes to production, often used as a measure of delivery speed.', 'Our deployment frequency went from once a week to several times a day.', '我们的部署频率从每周一次提升到了每天好几次。', ARRAY['devops', 'cloud']::text[], null, null, 409, true),
  ('dev-immutable-infrastructure', 'developer', 'immutable infrastructure', '不可变基础设施', 'n.', 'An approach where servers are never modified after deployment — instead, a new one replaces the old.', 'With immutable infrastructure, we replace the whole instance rather than patching it in place.', '在不可变基础设施下，我们是替换整个实例，而不是在原地打补丁。', ARRAY['devops', 'cloud']::text[], null, null, 410, true),
  ('dev-container-registry', 'developer', 'container registry', '容器镜像仓库', 'n.', 'A storage service used to store, version, and distribute container images.', 'The deployment pulls the latest image straight from the container registry.', '这次部署会直接从容器镜像仓库拉取最新的镜像。', ARRAY['devops', 'cloud']::text[], null, null, 411, true),
  ('dev-orchestration-tool', 'developer', 'orchestration tool', '编排工具', 'n.', 'Software that automates the deployment, scaling, and coordination of multiple services or containers.', 'The orchestration tool restarts any container that stops responding to health checks.', '这个编排工具会自动重启任何未能响应健康检查的容器。', ARRAY['devops', 'cloud']::text[], null, null, 412, true),
  ('dev-build-artifact', 'developer', 'build artifact', '构建产物', 'n.', 'The output produced by a build process, such as a compiled binary or package.', 'The same build artifact is promoted from staging to production without being rebuilt.', '同一个构建产物会从预发布环境直接晋升到生产环境，而不需要重新构建。', ARRAY['devops', 'cloud']::text[], null, null, 413, true),
  ('dev-reverse-proxy', 'developer', 'reverse proxy', '反向代理', 'n.', 'A server that sits in front of backend servers and forwards client requests to them.', 'The reverse proxy terminates TLS before forwarding the request to the application.', '反向代理会先终止 TLS 连接，再把请求转发给应用程序。', ARRAY['devops', 'cloud']::text[], null, null, 414, true),
  ('dev-package-manager', 'developer', 'package manager', '包管理器', 'n.', 'A tool that automates installing, updating, and removing software libraries and their dependencies.', 'The package manager flagged two dependencies with known vulnerabilities.', '这个包管理器标记出了两个存在已知漏洞的依赖。', ARRAY['devops', 'cloud']::text[], null, null, 415, true),
  ('dev-release-notes', 'developer', 'release notes', '发布说明', 'n.', 'A document summarizing what changed in a new software release.', 'Check the release notes before upgrading — this version removes an old API.', '升级之前先看一下发布说明——这个版本移除了一个旧接口。', ARRAY['reliability', 'monitoring']::text[], null, null, 416, true),
  ('dev-feature-flag', 'developer', 'feature flag', '功能开关', 'n.', 'A configuration switch that turns a feature on or off without deploying new code.', 'We shipped the new checkout behind a feature flag so it can be turned off instantly if needed.', '我们把新的结算功能放在了一个功能开关后面，需要时可以立刻关闭。', ARRAY['reliability', 'monitoring']::text[], null, null, 417, true),
  ('dev-monitoring-dashboard', 'developer', 'monitoring dashboard', '监控仪表盘', 'n.', 'A visual display of a system''s key metrics used to track its health in real time.', 'The monitoring dashboard showed error rates climbing minutes before users started reporting issues.', '在用户开始反馈问题的几分钟前，监控仪表盘上的错误率就已经开始攀升。', ARRAY['reliability', 'monitoring']::text[], null, null, 418, true),
  ('dev-alerting', 'developer', 'alerting', '告警', 'n.', 'Automatically notifying the responsible team when a metric crosses a defined threshold.', 'We set up alerting so the on-call engineer gets paged if latency exceeds two seconds.', '我们配置了告警机制，一旦延迟超过两秒，值班工程师就会收到寻呼通知。', ARRAY['reliability', 'monitoring']::text[], null, null, 419, true),
  ('dev-uptime', 'developer', 'uptime', '正常运行时间', 'n.', 'The amount of time a system remains available and operational.', 'The service maintained 99.9 percent uptime last quarter.', '这个服务上个季度维持了 99.9% 的正常运行时间。', ARRAY['reliability', 'monitoring']::text[], null, null, 420, true),
  ('dev-downtime', 'developer', 'downtime', '宕机时间', 'n.', 'A period during which a system is unavailable or not functioning.', 'We scheduled the maintenance for the middle of the night to minimize downtime.', '我们把维护安排在了半夜进行，以尽量减少宕机时间。', ARRAY['reliability', 'monitoring']::text[], null, null, 421, true),
  ('dev-service-level-agreement', 'developer', 'service level agreement', '服务级别协议', 'n.', 'A formal commitment defining the expected level of service, such as uptime or response time.', 'Our service level agreement promises a response to critical incidents within thirty minutes.', '我们的服务级别协议承诺在三十分钟内响应重大事故。', ARRAY['reliability', 'monitoring']::text[], null, null, 422, true),
  ('dev-incident-response', 'developer', 'incident response', '事故响应', 'n.', 'The organized process a team follows to detect, contain, and resolve a live production issue.', 'Our incident response plan starts with paging the on-call engineer.', '我们的事故响应流程第一步就是寻呼值班工程师。', ARRAY['reliability', 'monitoring']::text[], null, null, 423, true),
  ('dev-postmortem', 'developer', 'postmortem', '事后复盘', 'n.', 'A structured review after an incident that documents what happened and how to prevent it from recurring.', 'We wrote a blameless postmortem after the outage to capture the timeline and next steps.', '这次故障之后，我们写了一份不追责的事后复盘，记录了时间线和后续行动。', ARRAY['reliability', 'monitoring']::text[], null, null, 424, true),
  ('dev-on-call-rotation', 'developer', 'on-call rotation', '值班轮换', 'n.', 'A schedule that assigns team members to be responsible for responding to incidents during set periods.', 'I''m on the on-call rotation this week, so my phone stays on all night.', '这周我在值班轮换名单上，所以手机整晚都得开着。', ARRAY['reliability', 'monitoring']::text[], null, null, 425, true),
  ('dev-mean-time-to-recovery', 'developer', 'mean time to recovery', '平均恢复时间', 'n.', 'The average amount of time it takes to restore service after a failure.', 'Better runbooks cut our mean time to recovery in half.', '更完善的处置手册把我们的平均恢复时间缩短了一半。', ARRAY['reliability', 'monitoring']::text[], null, null, 426, true),
  ('dev-observability', 'developer', 'observability', '可观测性', 'n.', 'The ability to understand a system''s internal state from the logs, metrics, and traces it produces.', 'Better observability meant we could pinpoint the failing service within seconds.', '更好的可观测性让我们能在几秒钟内定位出故障服务。', ARRAY['reliability', 'monitoring']::text[], null, null, 427, true),
  ('dev-metrics', 'developer', 'metrics', '指标', 'n.', 'Numeric measurements collected over time to track a system''s behavior or performance.', 'We track latency and error rate as our two most important metrics.', '我们把延迟和错误率作为最重要的两个指标来追踪。', ARRAY['reliability', 'monitoring']::text[], null, null, 428, true),
  ('dev-distributed-tracing', 'developer', 'distributed tracing', '分布式追踪', 'n.', 'A method of tracking a single request as it flows through multiple services, to diagnose latency and errors.', 'Distributed tracing showed the request spent most of its time waiting on a single downstream service.', '分布式追踪显示这次请求的大部分时间都花在了等待某一个下游服务上。', ARRAY['reliability', 'monitoring']::text[], null, null, 429, true),
  ('dev-health-check', 'developer', 'health check', '健康检查', 'n.', 'An automated check that verifies whether a service is running correctly.', 'The load balancer stops routing traffic to any instance that fails its health check.', '负载均衡器会停止向任何未通过健康检查的实例分发流量。', ARRAY['reliability', 'monitoring']::text[], null, null, 430, true),
  ('dev-escalation-path', 'developer', 'escalation path', '升级路径（问题上报流程）', 'n.', 'The predefined sequence of people or teams to contact if an issue isn''t resolved quickly enough.', 'If the on-call engineer doesn''t respond in ten minutes, the escalation path pages their manager.', '如果值班工程师十分钟内没有响应，升级路径就会寻呼他们的主管。', ARRAY['reliability', 'monitoring']::text[], null, null, 431, true),
  ('dev-runbook', 'developer', 'runbook', '操作手册', 'n.', 'A step-by-step guide for handling a specific operational task or known type of incident.', 'The runbook walks the on-call engineer through restarting the failed service safely.', '这份操作手册一步步指导值班工程师安全地重启失败的服务。', ARRAY['reliability', 'monitoring']::text[], null, null, 432, true),
  ('dev-reliability-engineering', 'developer', 'reliability engineering', '可靠性工程', 'n.', 'A discipline focused on keeping systems available, performant, and resilient to failure.', 'Reliability engineering is why the system keeps running even when one region goes down.', '正是可靠性工程的实践，让这个系统在某个地区宕机时依然能保持运行。', ARRAY['reliability', 'monitoring']::text[], null, null, 433, true),
  ('dev-error-budget', 'developer', 'error budget', '错误预算', 'n.', 'The maximum amount of acceptable failure a service can have while still meeting its reliability target.', 'We paused new feature launches after burning through this quarter''s error budget.', '在用完这个季度的错误预算后，我们暂停了新功能的上线。', ARRAY['reliability', 'monitoring']::text[], null, null, 434, true),
  ('dev-root-cause-analysis', 'developer', 'root cause analysis', '根因分析', 'n.', 'A structured process for identifying the true underlying cause of a problem.', 'The root cause analysis traced the outage back to a single misconfigured retry policy.', '这次根因分析最终把故障追溯到了一个配置错误的重试策略上。', ARRAY['reliability', 'monitoring']::text[], null, null, 435, true),
  ('dev-rollout', 'developer', 'rollout', '推出（发布）', 'n.', 'The gradual or full release of a new version or feature to users.', 'We paused the rollout at ten percent of users after seeing an unexpected spike in crashes.', '在发现崩溃率意外飙升后，我们在覆盖 10% 用户时暂停了这次推出。', ARRAY['reliability', 'monitoring']::text[], null, null, 436, true),
  ('dev-hotfix-release', 'developer', 'hotfix release', '紧急修复版本', 'n.', 'An out-of-cycle release that ships a critical fix outside the normal release schedule.', 'We shipped a hotfix release within an hour of confirming the payment bug.', '在确认这个支付相关的 bug 之后一小时内，我们就发布了一个紧急修复版本。', ARRAY['reliability', 'monitoring']::text[], null, null, 437, true),
  ('dev-status-page', 'developer', 'status page', '状态页', 'n.', 'A public page that reports the current operational status and any ongoing incidents of a service.', 'We posted an update on the status page as soon as the incident was confirmed.', '确认这次事故之后，我们立刻在状态页上发布了更新。', ARRAY['reliability', 'monitoring']::text[], null, null, 438, true),
  ('dev-alert-fatigue', 'developer', 'alert fatigue', '告警疲劳', 'n.', 'A state where engineers become desensitized to alerts because there are too many low-value ones.', 'We tuned the thresholds to reduce alert fatigue on the on-call team.', '我们调整了告警阈值，以减轻值班团队的告警疲劳。', ARRAY['reliability', 'monitoring']::text[], null, null, 439, true),
  ('dev-service-degradation', 'developer', 'service degradation', '服务降级', 'n.', 'A state where a service is still running but performing noticeably worse than normal.', 'Users reported service degradation before the dashboard showed any red alerts.', '在仪表盘出现红色告警之前，用户就已经反馈了服务降级的情况。', ARRAY['reliability', 'monitoring']::text[], null, null, 440, true),
  ('dev-disaster-recovery', 'developer', 'disaster recovery', '灾难恢复', 'n.', 'The plans and procedures used to restore systems and data after a major failure or catastrophe.', 'We test our disaster recovery plan by simulating a full region outage every quarter.', '我们每个季度都会模拟一次整个地区宕机，来测试灾难恢复计划。', ARRAY['reliability', 'monitoring']::text[], null, null, 441, true),
  ('dev-chaos-engineering', 'developer', 'chaos engineering', '混沌工程', 'n.', 'Deliberately injecting failures into a system to test its resilience before real incidents happen.', 'Chaos engineering revealed a hidden dependency that would have caused a full outage.', '混沌工程实验揭示了一个隐藏的依赖关系，若不修复本会导致一次全面宕机。', ARRAY['reliability', 'monitoring']::text[], null, null, 442, true),
  ('dev-log-retention', 'developer', 'log retention', '日志保留期', 'n.', 'The policy defining how long logs are kept before being deleted or archived.', 'We extended log retention to ninety days to support longer investigations.', '我们把日志保留期延长到了九十天，以支持更长时间跨度的排查。', ARRAY['reliability', 'monitoring']::text[], null, null, 443, true),
  ('dev-release-cadence', 'developer', 'release cadence', '发布节奏', 'n.', 'The regular rhythm or schedule at which a team ships new releases.', 'We settled on a two-week release cadence to balance stability and speed.', '我们最终确定了两周一次的发布节奏，以兼顾稳定性和速度。', ARRAY['reliability', 'monitoring']::text[], null, null, 444, true),
  ('dev-requirements-gathering', 'developer', 'requirements gathering', '需求收集', 'n.', 'The process of collecting and understanding what stakeholders need from a feature or system.', 'We spent the first week on requirements gathering before writing a single line of code.', '在写下第一行代码之前，我们花了第一周的时间做需求收集。', ARRAY['communication', 'collaboration']::text[], null, null, 445, true),
  ('dev-design-doc', 'developer', 'design doc', '设计文档', 'n.', 'A written document that lays out the proposed approach, trade-offs, and details for a piece of work before it''s built.', 'Share the design doc with the team before you start implementation.', '在开始实现之前，先把设计文档分享给团队。', ARRAY['communication', 'collaboration']::text[], null, null, 446, true),
  ('dev-sprint-planning', 'developer', 'sprint planning', '迭代计划会议', 'n.', 'A meeting at the start of a sprint where the team decides what work to commit to.', 'We reprioritized the backlog right before sprint planning.', '我们在迭代计划会议之前重新排列了待办事项的优先级。', ARRAY['communication', 'collaboration']::text[], null, null, 447, true),
  ('dev-standup-meeting', 'developer', 'standup meeting', '站会', 'n.', 'A short daily meeting where team members share progress, plans, and blockers.', 'I mentioned the blocked deployment during this morning''s standup meeting.', '我在今天早上的站会上提到了部署被阻塞的情况。', ARRAY['communication', 'collaboration']::text[], null, null, 448, true),
  ('dev-retrospective', 'developer', 'retrospective', '回顾会议', 'n.', 'A recurring meeting where a team reflects on what went well and what to improve.', 'We brought up the deployment issues in the sprint retrospective.', '我们在这次迭代的回顾会议上提出了部署方面的问题。', ARRAY['communication', 'collaboration']::text[], null, null, 449, true),
  ('dev-handoff', 'developer', 'handoff', '交接', 'n.', 'Transferring responsibility for a task, project, or on-call duty from one person or team to another.', 'We documented everything before the handoff to the support team.', '在交接给支持团队之前，我们把所有信息都记录了下来。', ARRAY['communication', 'collaboration']::text[], null, null, 450, true),
  ('dev-cross-functional-team', 'developer', 'cross-functional team', '跨职能团队', 'n.', 'A team that includes members from different disciplines, such as engineering, design, and product.', 'This feature was built by a cross-functional team of engineers, designers, and a product manager.', '这个功能是由一个包含工程师、设计师和产品经理的跨职能团队一起完成的。', ARRAY['communication', 'collaboration']::text[], null, null, 451, true),
  ('dev-escalate-an-issue', 'developer', 'escalate an issue', '上报问题', 'phr.', 'To raise a problem to someone with more authority or context when it can''t be resolved at the current level.', 'If the vendor doesn''t respond by tomorrow, we''ll need to escalate an issue to their account manager.', '如果供应商明天还没回应，我们就需要把这个问题上报给他们的客户经理。', ARRAY['communication', 'collaboration']::text[], null, null, 452, true),
  ('dev-clarify-requirements', 'developer', 'clarify requirements', '澄清需求', 'phr.', 'To ask questions and confirm details so a requirement is fully and correctly understood.', 'I scheduled a quick call to clarify requirements before estimating the work.', '在给这项工作做估算之前，我安排了一次简短的通话来澄清需求。', ARRAY['communication', 'collaboration']::text[], null, null, 453, true),
  ('dev-edge-case-discussion', 'developer', 'edge case discussion', '边界情况讨论', 'n.', 'A conversation focused on identifying unusual scenarios a design or requirement might not have considered.', 'The edge case discussion surfaced a scenario the original spec never mentioned.', '这次边界情况讨论发现了一个原始需求文档从未提到过的场景。', ARRAY['communication', 'collaboration']::text[], null, null, 454, true),
  ('dev-scope-alignment', 'developer', 'scope alignment', '范围对齐', 'n.', 'Reaching shared agreement among stakeholders on exactly what is and isn''t included in a piece of work.', 'We held a short meeting for scope alignment before committing to a deadline.', '在承诺截止日期之前，我们开了一个简短的会议来做范围对齐。', ARRAY['communication', 'collaboration']::text[], null, null, 455, true),
  ('dev-knowledge-sharing', 'developer', 'knowledge sharing', '知识共享', 'n.', 'Actively passing expertise or context from one team member to others.', 'We hold a weekly knowledge sharing session so no single person is the only one who understands a system.', '我们每周都会举办一次知识共享分享会，避免某个系统只有一个人懂。', ARRAY['communication', 'collaboration']::text[], null, null, 456, true),
  ('dev-documentation', 'developer', 'documentation', '文档', 'n.', 'Written material that explains how a system works or how to use it.', 'The documentation was out of date, which cost the new engineer half a day.', '文档已经过时了，这让新来的工程师白白花了半天时间。', ARRAY['communication', 'collaboration']::text[], null, null, 457, true),
  ('dev-onboarding', 'developer', 'onboarding', '入职引导', 'n.', 'The process of helping a new team member get set up and productive.', 'Our onboarding checklist gets a new engineer to their first deployed change within a week.', '我们的入职引导清单能让一名新工程师在一周内就完成第一次上线改动。', ARRAY['communication', 'collaboration']::text[], null, null, 458, true),
  ('dev-code-walkthrough', 'developer', 'code walkthrough', '代码讲解', 'n.', 'A session where a developer explains a piece of code to others, often to share context or gather feedback.', 'I gave a code walkthrough of the new billing module to the rest of the team.', '我给团队其他成员做了一次新计费模块的代码讲解。', ARRAY['communication', 'collaboration']::text[], null, null, 459, true),
  ('dev-design-review', 'developer', 'design review', '设计评审', 'n.', 'A meeting where a proposed technical design is presented and critiqued before implementation begins.', 'The design review raised concerns about how the system would scale.', '这次设计评审提出了对系统可扩展性的担忧。', ARRAY['communication', 'collaboration']::text[], null, null, 460, true),
  ('dev-trade-off', 'developer', 'trade-off', '权衡取舍', 'n.', 'A balance struck between two competing options, where gaining one thing means giving up another.', 'There''s a trade-off between shipping fast and keeping the code maintainable.', '在快速上线和保持代码可维护性之间，存在一个权衡取舍。', ARRAY['communication', 'collaboration']::text[], null, null, 461, true),
  ('dev-stakeholder-buy-in', 'developer', 'stakeholder buy-in', '相关方支持', 'n.', 'Agreement and support from key stakeholders before proceeding with a plan.', 'We got stakeholder buy-in on the new timeline before communicating it to the wider team.', '我们先获得了相关方对新时间表的支持，然后才把它传达给更大范围的团队。', ARRAY['communication', 'collaboration']::text[], null, null, 462, true),
  ('dev-action-item', 'developer', 'action item', '行动项', 'n.', 'A specific, assigned task that comes out of a meeting or discussion.', 'Each action item from the postmortem was assigned an owner and a due date.', '复盘会议中的每一个行动项都指定了负责人和截止日期。', ARRAY['communication', 'collaboration']::text[], null, null, 463, true),
  ('dev-follow-up', 'developer', 'follow-up', '跟进', 'n.', 'A subsequent message or meeting checking on the progress or outcome of something already discussed.', 'I sent a follow-up to confirm whether the fix had actually resolved the issue.', '我发了一条跟进消息，确认这个修复是否真正解决了问题。', ARRAY['communication', 'collaboration']::text[], null, null, 464, true),
  ('dev-blocker-communication', 'developer', 'blocker', '阻碍因素', 'n.', 'Something that is preventing a person or team from making progress on their work.', 'Waiting on design assets is my biggest blocker this week.', '等待设计素材是我这周最大的阻碍因素。', ARRAY['communication', 'collaboration']::text[], null, null, 465, true),
  ('dev-pushback', 'developer', 'pushback', '反对意见；异议', 'n.', 'Resistance or objection raised in response to a proposal or decision.', 'We got pushback from the security team on storing the data unencrypted.', '对于未加密存储这些数据的方案，我们收到了安全团队的反对意见。', ARRAY['communication', 'collaboration']::text[], null, null, 466, true),
  ('dev-consensus-building', 'developer', 'consensus building', '达成共识', 'n.', 'The process of working with multiple people to reach an agreement everyone can support.', 'Consensus building took longer than the implementation itself.', '达成共识花的时间比实际实现这个功能还要长。', ARRAY['communication', 'collaboration']::text[], null, null, 467, true),
  ('dev-async-communication', 'developer', 'async communication', '异步沟通', 'n.', 'Communication that doesn''t require both parties to be available at the same time, such as written messages.', 'We rely on async communication across time zones instead of scheduling every discussion live.', '面对跨时区协作，我们更依赖异步沟通，而不是每次讨论都安排实时会议。', ARRAY['communication', 'collaboration']::text[], null, null, 468, true),
  ('dev-status-update', 'developer', 'status update', '进展汇报', 'n.', 'A brief report on the current progress of a task or project.', 'Send a status update to the stakeholders every Friday afternoon.', '每周五下午都要给相关方发送一次进展汇报。', ARRAY['communication', 'collaboration']::text[], null, null, 469, true),
  ('dev-requirement-ambiguity', 'developer', 'requirement ambiguity', '需求歧义', 'n.', 'A situation where a requirement can be reasonably interpreted in more than one way.', 'The requirement ambiguity around ''active user'' led two teams to build different definitions.', '围绕“活跃用户”这个概念的需求歧义，导致两个团队分别实现了不同的定义。', ARRAY['communication', 'collaboration']::text[], null, null, 470, true),
  ('dev-technical-writing', 'developer', 'technical writing', '技术写作', 'n.', 'Writing clear, structured documents that explain technical concepts, systems, or processes.', 'Strong technical writing skills made her design docs easy for anyone to follow.', '扎实的技术写作能力让她写的设计文档任何人都能轻松看懂。', ARRAY['communication', 'collaboration']::text[], null, null, 471, true),
  ('dev-feedback-loop', 'developer', 'feedback loop', '反馈循环', 'n.', 'A cycle in which the results of an action are used to inform and improve future actions.', 'A tight feedback loop with users helped us catch usability problems early.', '与用户之间紧密的反馈循环帮助我们尽早发现了可用性问题。', ARRAY['communication', 'collaboration']::text[], null, null, 472, true),
  ('dev-tech-stack', 'developer', 'tech stack', '技术栈', 'n.', 'The combination of programming languages, frameworks, and tools used to build a product.', 'Could you walk me through the tech stack you used for this project?', '能不能介绍一下你在这个项目中使用的技术栈？', ARRAY['interview', 'career']::text[], null, null, 473, true),
  ('dev-take-ownership', 'developer', 'take ownership', '主动承担责任', 'phr.', 'To fully accept responsibility for a task or outcome, including seeing it through to completion.', 'I took ownership of the migration from start to finish, including the rollback plan.', '我主动承担了这次迁移从头到尾的责任，包括制定回滚方案。', ARRAY['interview', 'career']::text[], null, null, 474, true),
  ('dev-deep-dive', 'developer', 'deep dive', '深入探讨', 'n.', 'A thorough, detailed examination of a specific topic or piece of work.', 'The interviewer asked for a deep dive into how I debugged the production incident.', '面试官让我深入探讨一下当时是如何排查那次生产事故的。', ARRAY['interview', 'career']::text[], null, null, 475, true),
  ('dev-questions-for-the-interviewer', 'developer', 'questions for the interviewer', '反问面试官的问题', 'n.', 'Questions a candidate prepares to ask the interviewer, usually near the end of the interview.', 'Always prepare a few thoughtful questions for the interviewer about the team and the role.', '一定要提前准备几个有深度的问题，用来反问面试官关于团队和这个岗位的情况。', ARRAY['interview', 'career']::text[], null, null, 476, true),
  ('dev-walk-through-your-code', 'developer', 'walk through your code', '讲解你的代码', 'phr.', 'A request to explain a piece of code line by line, including the reasoning behind it.', 'Can you walk through your code and explain why you chose this approach?', '你能讲解一下你的代码，说说为什么选择这种实现方式吗？', ARRAY['interview', 'career']::text[], null, null, 477, true),
  ('dev-whiteboard-interview', 'developer', 'whiteboard interview', '白板面试', 'n.', 'An interview format where a candidate solves a coding or design problem on a whiteboard, often live.', 'The whiteboard interview focused on a graph problem and how I''d explain my reasoning out loud.', '这次白板面试聚焦在一道图论题目，以及我如何把思路大声讲出来。', ARRAY['interview', 'career']::text[], null, null, 478, true),
  ('dev-take-home-assignment', 'developer', 'take-home assignment', '带回家完成的测试题', 'n.', 'A coding or design task a candidate completes independently, outside the interview, within a given deadline.', 'The take-home assignment asked us to build a small API within a week.', '这次带回家完成的测试题要求我们在一周内实现一个小型 API。', ARRAY['interview', 'career']::text[], null, null, 479, true),
  ('dev-behavioral-question', 'developer', 'behavioral question', '行为面试问题', 'n.', 'An interview question that asks about a real past experience to predict how a candidate handles similar situations.', 'The behavioral question asked me to describe a time I disagreed with a teammate.', '这个行为面试问题让我描述一次和同事意见不合的经历。', ARRAY['interview', 'career']::text[], null, null, 480, true),
  ('dev-technical-screen', 'developer', 'technical screen', '技术初筛面试', 'n.', 'An early-stage interview, often shorter, used to verify a candidate''s baseline technical ability.', 'The technical screen was a thirty-minute call covering basic data structure questions.', '这次技术初筛面试是一通三十分钟的电话，主要考察基础的数据结构问题。', ARRAY['interview', 'career']::text[], null, null, 481, true),
  ('dev-system-design-interview', 'developer', 'system design interview', '系统设计面试', 'n.', 'An interview round focused on designing a large-scale system, evaluating architecture and trade-off decisions.', 'In the system design interview, I was asked to design a URL shortening service.', '在这次系统设计面试中，我被要求设计一个短链接服务。', ARRAY['interview', 'career']::text[], null, null, 482, true),
  ('dev-coding-challenge', 'developer', 'coding challenge', '编程测试题', 'n.', 'A programming problem given to a candidate to assess their coding ability, often under time pressure.', 'The online coding challenge had a strict ninety-minute time limit.', '这次在线编程测试题有严格的九十分钟时间限制。', ARRAY['interview', 'career']::text[], null, null, 483, true),
  ('dev-pair-programming-interview', 'developer', 'pair programming interview', '结对编程面试', 'n.', 'An interview format where the candidate writes code together with an interviewer in real time.', 'The pair programming interview let me show how I actually communicate while coding.', '这次结对编程面试让我能够展示自己在编码时的实际沟通方式。', ARRAY['interview', 'career']::text[], null, null, 484, true),
  ('dev-strengths-and-weaknesses', 'developer', 'strengths and weaknesses', '优点和缺点', 'n.', 'A common interview topic asking a candidate to reflect honestly on their strong and weak points.', 'When asked about my strengths and weaknesses, I gave a concrete example for each.', '被问到优点和缺点时，我为每一点都举了一个具体的例子。', ARRAY['interview', 'career']::text[], null, null, 485, true),
  ('dev-greatest-achievement', 'developer', 'greatest achievement', '最大成就', 'n.', 'A common interview prompt asking a candidate to describe their proudest professional accomplishment.', 'My greatest achievement was leading the migration that cut our infrastructure costs by a third.', '我最大的成就是主导了一次把基础设施成本降低了三分之一的迁移工作。', ARRAY['interview', 'career']::text[], null, null, 486, true),
  ('dev-describe-a-challenge', 'developer', 'describe a challenge', '描述一次挑战', 'phr.', 'A common interview prompt asking a candidate to explain a difficult situation and how they handled it.', 'Describe a challenge you faced when a project''s requirements changed midway through.', '描述一次项目需求在中途发生变化时你面对的挑战。', ARRAY['interview', 'career']::text[], null, null, 487, true),
  ('dev-handle-conflict', 'developer', 'handle conflict', '处理冲突', 'phr.', 'To manage a disagreement between people constructively, a common behavioral interview topic.', 'How do you handle conflict when a teammate disagrees with your technical decision?', '当同事不认同你的技术决定时，你是如何处理冲突的？', ARRAY['interview', 'career']::text[], null, null, 488, true),
  ('dev-career-growth', 'developer', 'career growth', '职业发展', 'n.', 'The advancement of a person''s skills, responsibilities, and role over time.', 'I''m looking for a role that offers real career growth, not just a title change.', '我在找一个能带来真正职业发展的岗位，而不只是换个头衔。', ARRAY['interview', 'career']::text[], null, null, 489, true),
  ('dev-cross-team-collaboration', 'developer', 'cross-team collaboration', '跨团队协作', 'n.', 'Working effectively with people from teams outside your own to achieve a shared goal.', 'This project required close cross-team collaboration with the mobile and design teams.', '这个项目需要和移动端团队、设计团队进行密切的跨团队协作。', ARRAY['interview', 'career']::text[], null, null, 490, true),
  ('dev-fast-paced-environment', 'developer', 'fast-paced environment', '快节奏的工作环境', 'n.', 'A workplace where priorities, projects, or demands change quickly and often.', 'I thrive in a fast-paced environment where priorities can shift within a day.', '我在优先级一天之内就可能变化的快节奏工作环境中表现得很出色。', ARRAY['interview', 'career']::text[], null, null, 491, true),
  ('dev-self-starter', 'developer', 'self-starter', '自我驱动的人', 'n.', 'A person who takes initiative and starts working on tasks without needing to be told.', 'The job posting says they''re looking for a self-starter who can work with minimal supervision.', '这份招聘启事说他们在找一个能在很少监督下工作、自我驱动的人。', ARRAY['interview', 'career']::text[], null, null, 492, true),
  ('dev-learning-curve', 'developer', 'learning curve', '学习曲线', 'n.', 'The rate at which a person gains new skills or knowledge, often used to describe how hard something is to pick up.', 'There''s a steep learning curve with this framework, but it pays off after the first few weeks.', '这个框架的学习曲线很陡，但坚持过最初几周之后就会觉得值得。', ARRAY['interview', 'career']::text[], null, null, 493, true),
  ('dev-onboarding-process', 'developer', 'onboarding process', '入职流程', 'n.', 'The structured set of steps a new hire goes through to get set up and productive at a new job.', 'I asked about the onboarding process to understand how quickly new engineers start shipping.', '我询问了入职流程，想了解新工程师大概多久能开始正式上线代码。', ARRAY['interview', 'career']::text[], null, null, 494, true),
  ('dev-compensation-expectations', 'developer', 'compensation expectations', '薪资期望', 'n.', 'The salary and benefits range a candidate is looking for, often discussed in later interview rounds.', 'The recruiter asked about my compensation expectations before scheduling the next round.', '招聘人员在安排下一轮面试之前询问了我的薪资期望。', ARRAY['interview', 'career']::text[], null, null, 495, true),
  ('dev-notice-period', 'developer', 'notice period', '离职通知期', 'n.', 'The amount of time an employee must work after resigning before officially leaving the company.', 'My notice period is one month, so I could start the new role in early next month.', '我的离职通知期是一个月，所以下个月初就可以开始新的岗位。', ARRAY['interview', 'career']::text[], null, null, 496, true),
  ('dev-growth-mindset', 'developer', 'growth mindset', '成长型思维', 'n.', 'The belief that abilities can be developed through effort and learning, rather than being fixed.', 'I try to approach every failed deployment with a growth mindset instead of getting discouraged.', '面对每一次失败的部署，我都尽量用成长型思维去看待，而不是感到气馁。', ARRAY['interview', 'career']::text[], null, null, 497, true),
  ('dev-problem-solving-skills', 'developer', 'problem-solving skills', '问题解决能力', 'n.', 'The ability to analyze a difficult situation and find an effective solution.', 'This interview question was really testing my problem-solving skills under time pressure.', '这道面试题实际上是在测试我在时间压力下的问题解决能力。', ARRAY['interview', 'career']::text[], null, null, 498, true),
  ('dev-collaborate-cross-functionally', 'developer', 'collaborate cross-functionally', '跨职能协作', 'phr.', 'To work closely with people in different roles or departments toward a shared goal.', 'This role requires you to collaborate cross-functionally with design, product, and QA.', '这个岗位需要你和设计、产品、QA 等不同职能的同事进行跨职能协作。', ARRAY['interview', 'career']::text[], null, null, 499, true),
  ('pm-milestone', 'project-manager', 'milestone', '里程碑', 'n.', 'A significant point or event marking progress in a project.', 'Reaching the beta release is our next major milestone.', '发布测试版是我们下一个重要的里程碑。', ARRAY['planning', 'workplace']::text[], 'ˈmaɪlˌstoʊn', null, 0, true),
  ('pm-deliverable', 'project-manager', 'deliverable', '交付物', 'n.', 'A tangible or intangible output produced as part of a project.', 'The final deliverable includes both the report and the source files.', '最终交付物包括报告和源文件。', ARRAY['planning', 'workplace']::text[], 'dɪˈlɪvərəbəl', null, 1, true),
  ('pm-scope-creep', 'project-manager', 'scope creep', '范围蔓延（需求不断扩大）', 'n.', 'Uncontrolled expansion of a project scope after it has started.', 'Without a change process, scope creep can quickly derail the timeline.', '如果没有变更流程，范围蔓延会很快打乱项目进度。', ARRAY['risk', 'planning']::text[], 'skoʊp kriːp', null, 2, true),
  ('pm-risk-mitigation', 'project-manager', 'risk mitigation', '风险缓解', 'n.', 'Actions taken to reduce the likelihood or impact of a risk.', 'Our risk mitigation plan covers vendor delays and staff turnover.', '我们的风险缓解计划涵盖了供应商延误和人员流动的情况。', ARRAY['risk', 'planning']::text[], 'rɪsk ˌmɪtɪˈɡeɪʃən', null, 3, true),
  ('pm-sprint', 'project-manager', 'sprint', '冲刺（迭代周期）', 'n.', 'A fixed, short time period in which a team completes a set of work.', 'We review progress at the end of every two-week sprint.', '我们在每两周一次的冲刺结束时回顾进度。', ARRAY['agile', 'workplace']::text[], 'sprɪnt', null, 4, true),
  ('pm-backlog', 'project-manager', 'backlog', '待办事项列表；产品积压', 'n.', 'A list of tasks or features waiting to be worked on.', 'We groomed the backlog before sprint planning to reprioritize the top items.', '我们在迭代规划之前梳理了待办事项列表，重新排列了优先级最高的几项。', ARRAY['planning', 'agile']::text[], 'ˈbækˌlɔɡ', null, 5, true),
  ('pm-resource-allocation', 'project-manager', 'resource allocation', '资源分配', 'n.', 'The process of assigning available people, time, or budget to specific tasks.', 'Poor resource allocation left two teams short-staffed during the launch.', '资源分配不当导致两个团队在上线期间人手不足。', ARRAY['planning', 'workplace']::text[], 'ˈrisɔrs ˌæləˈkeɪʃən', null, 6, true),
